COLLDATA("tadabburar","ar",[[457,"§صٓ\nwords\nأَتَّخَذنَاهُم سِخرِيًّاهَل تَحقِيرُنَا لَهُم خَطَأٌ؟\nزَاغَتمَالَت، فَلَم تَقَع عَلَيهِم.\nبِالمَلَأِ الأَعلَىالمَلاَئِكَةِ.\nيَختَصِمُونَيَتَجَادَلُونَ فِي شَأنِ خَلقِ آدَمَ -عليه السلام-.\nسَوَّيتُهُخَلَقتُ جَسَدَهُ كَامِلًا مُتَنَاسِقَ الأعضَاءِ.\nسَاجِدِينَسُجُودَ تَحِيَّةٍ وَإِكرَامٍ، لاَ سُجُودَ عِبَادَةٍ وَتَعظِيمٍ.\nلَأُغوِيَنَّهُملَأُضِلَّنَّهُم.\ndeeds\nاستسمح مسلمًا سخرت منه في يوم من الأيام، أو تصدق عنه، وادعُ له بالمغفرة، مع التوبة النصوح.\nاستعذ بالله من إغواء الشيطان، واتباع خطواته.\nادع الله تعالى أن يجعلك من عباده المخلَصين.\nguid\nخصومة أهل النار عذاب نفسي فوق العذاب الحسي.\nعالج أمراض النفس -كالكبر والحسد- بالدعاء لمن أصيبوا بها.\nاحذر الأنفة في غير محلها والكبر؛ فهو الذنب الذي دخل به إبليس النار.\nrefl\nوَقَالُواْ مَا لَنَا لَا نَرَىٰ رِجَالٗا كُنَّا نَعُدُّهُم مِّنَ ٱلۡأَشۡرَارِ ٦٢\nأي كنا نحسبهم أشقياء؛ قد خسروا لذة الحياة باتباعهم الإسلام ورضاهم بشظف العيش. ابن عاشور:٢٣/٢٩٢.\nمن العذاب النفسي لأهل النار اكتشافهم خطأ موازينهم التي كانوا يقيسون بها الناس في الدنيا، وضح ذلك من الآية.\nقُلۡ إِنَّمَآ أَنَا۠ مُنذِرٞۖ وَمَا مِنۡ إِلَٰهٍ إِلَّا ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ ٦٥\nهذا تقرير لألوهيته بهذا البرهان القاطع؛ وهو وحدته تعالى وقهره لكل شيء؛ فإن القهر ملازم للوحدة، فلا يكون قهاران متساويان في قهرهما أبدًا؛ فالذي يقهر جميع الأشياء هو الواحد الذي لا نظير له، وهو الذي يستحق أن يُعبد وحده كما كان قاهرًا وحده. السعدي:٧١٦.\nلماذا قرن الله -سبحانه وتعالى- بين صفتيه ﴿ٱلۡوَٰحِدُ ٱلۡقَهَّارُ﴾؟\nقُلۡ هُوَ نَبَؤٌاْ عَظِيمٌ ٦٧\n(قل) لهم مخوفًا ومحذرًا ومنهضًا لهم ومنذرًا: (هو نبأ عظيم) أي: ما أنبأتكم به من البعث والنشور والجزاء على الأعمال خبر عظيم ينبغي الاهتمام الشديد بشأنه، ولا ينبغي إغفاله. السعدي:٧١٦.\nإذا علمت أن يوم القيامة والحساب نبأ عظيم وأمر جسيم، فما الذي ينبغي عليك؟\nإِلَّآ إِبۡلِيسَ ٱسۡتَكۡبَرَ وَكَانَ مِنَ ٱلۡكَٰفِرِينَ ٧٤\nوقد بدت من إبليس نزعة كانت كامنة في جبلته؛ وهي نزعة الكبر والعصيان، ولم تكن تظهر منه قبل ذلك لأن الملأ الذي كان معهم كانوا على أكمل حسن الخلطة فلم يكن منهم مثير لما سكن في نفسه من طبع الكبر والعصيان، فلما طرأ على ذلك الملأ مخلوق جديد، وأُمِر أهل الملأ الأعلى بتعظيمه، كان ذلك مورِيًا زناد الكبر في نفس إبليس، فنشأ عنه الكفر بالله وعصيان أمره. ابن عاشور:٢٣/٣٠١.\nما سبب ظهور نزعة الكبر عند ابليس؟\nقَالَ يَٰٓإِبۡلِيسُ مَا مَنَعَكَ أَن تَسۡجُدَ لِمَا خَلَقۡتُ بِيَدَيَّۖ أَسۡتَكۡبَرۡتَ أَمۡ كُنتَ مِنَ ٱلۡعَالِينَ ٧٥ قَالَ أَنَا۠ خَيۡرٞ مِّنۡهُ خَلَقۡتَنِي مِن نَّارٖ وَخَلَقۡتَهُۥ مِن طِينٖ ٧٦\nوهذا تقريع من الله للمشركين الذين كفروا بمحمد -صلى الله عليه وسلم-... استكبارًا عن أن يكونوا تبعًا لرجل منهم حين قالوا: ﴿أَءُنزِلَ عَلَيۡهِ ٱلذِّكۡرُ مِنۢ بَيۡنِنَا﴾ [ص: ٨]، و﴿هَلۡ هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡ﴾ [الأنبياء: ٣]؛ فقص عليهم تعالى قصة إبليس وإهلاكه باستكباره عن السجود لآدم بدعواه أنه خير منه. الطبري:٢١/٢٣٩.\nما المناسبة بين قصة إبليس وموقف كفار قريش من نبينا محمد -صلى الله عليه وسلم-؟\nقَالَ رَبِّ فَأَنظِرۡنِيٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ ٧٩ قَالَ فَإِنَّكَ مِنَ ٱلۡمُنظَرِينَ ٨٠ إِلَىٰ يَوۡمِ ٱلۡوَقۡتِ ٱلۡمَعۡلُومِ ٨١\nسأل الله النظرة إلى يوم البعث فأنظره الحليم الذي لا يعجل على من عصاه. فلما أمن الهلاك إلى يوم القيامة تمرد وطغى وقال: ﴿لَأُغۡوِيَنَّهُمۡ أَجۡمَعِينَ إِلَّا عِبَادَكَ مِنۡهُمُ ٱلۡمُخۡلَصِينَ﴾. ابن كثير:٤/٤٥.\nما الصفة الإلهية التي تفيدها من استجابة الله سبحانه لطلب إبليس بالإنظار؟\nقَالَ فَبِعِزَّتِكَ لَأُغۡوِيَنَّهُمۡ أَجۡمَعِينَ ٨٢\nلمَّا طرده بسبب آدم حلف بعزة الله أنه يضل بني آدم؛ بتزيين الشهوات، وإدخال الشبه عليهم. القرطبي:١٨/٢٤٠.\nما وسائل الشيطان في إضلال بني آدم؟"],[458,"§صٓ ، الزمر\nwords\nأَجرٍجَزَاءٍ وَأُجرَةٍ عَلَى الهِدَايَةِ وَالدَّعوَةِ.\nالمُتَكَلِّفِينَالمُتَصَنِّعِينَ المُتَقَوِّلِينَ عَلَى اللهِ.\nنَبَأَهُخَبَرَ القُرآنِ وَصِدقَهُ.\nمُخلِصًا لَهُ الدِّينَمُوَحِّدًا لَهُ العِبَادَةَ وَالطَّاعَةَ.\nالدِّينُ الخَالِصُالطَّاعَةُ التَّامَّةُ السَّالِمَةُ مِنَ الشِّركِ.\nزُلفَىتَقَرُّبًا.\nلاَصطَفَىلاَختَارَ.\nيُكَوِّرُيُدخِلُ.\ndeeds\nاستعذ بالله من النار؛ فهي مصير أتباع إبليس.\nادع الله تعالى أن يكون توحيدك خالصًا له، لا يشوبه شرك أو رياء.\nتأمل دوران الشمس والقمر وما فيه من العبر.\nguid\nإن استطعت أن لا تسأل على دعوتك أجرًا إلا من الله تعالى؛ فافعل.\nالله -عز وجل- لا يقبل إلا العبادة الخالصة، فاحرص أن تكون أعمالك كلها كذلك.\nذم الكذب والتقوُّل على الله والرسول والمؤمنين.\nrefl\nقُلۡ مَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٖ وَمَآ أَنَا۠ مِنَ ٱلۡمُتَكَلِّفِينَ ٨٦\nعن مسروق قال: أتينا عبد الله بن مسعود -رضي الله عنه- قال: \"يا أيها الناس من علم شيئًا فليقل به، ومن لم يعلم فليقل: الله أعلم؛ فإن من العلم أن يقول الرجل لما لا يعلم: الله أعلم؛ فإن الله -عز وجل- قال لنبيكم -صلى الله عليه وسلم-: ﴿قُلۡ مَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍ وَمَآ أَنَا۠ مِنَ ٱلۡمُتَكَلِّفِينَ﴾\". ابن كثير:٤/٤٥.\nاستنبط عبد الله بن مسعود أدبًا من آداب طلبة العلم من خلال تدبره للآية، ما هو؟\nقُلۡ مَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٖ وَمَآ أَنَا۠ مِنَ ٱلۡمُتَكَلِّفِينَ ٨٦\nوأخذ من قوله: ﴿وَمَآ أَنَا۠ مِنَ ٱلۡمُتَكَلِّفِينَ﴾ أن ما جاء به من الدين لا تكلف فيه؛ أي: لا مشقة في تكاليفه؛ وهو معنى سماحة الإِسلام، وهذا استرواح مبني على أن من حكمة الله أن يجعل بين طبع الرسول -صلى الله عليه وسلم- وبين روح شريعته تناسبًا. ابن عاشور:٢٣/٣٠٩.\nبيّن سماحة الاسلام من خلال الآية الكريمة.\nإِنۡ هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ ٨٧\nهذه السورة العظيمة مشتملة على الذكر الحكيم... فلهذا أقسم في أولها بأنه ذو الذكر، ووصفه في آخرها بأنه ذكر للعالمين، وأكثرَ التذكير بها فيما بين ذلك؛ كقوله: ﴿وَٱذۡكُرۡ عَبۡدَنَا﴾، ﴿وَٱذۡكُرۡ عَبۡدَنَا﴾، ﴿رَحۡمَةً مِّنَّا وَذِكۡرَىٰ﴾، ﴿هَٰذَا ذِكۡرُ﴾. السعدي: ٧١٧.\nما أكثر أمر اشتملت عليه السورة؟ اذكر فائدتين من ذلك.\nتَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ ١\nالكلام وصف للمتكلم، والوصف يتبع الموصوف، فكما أن الله تعالى الكامل من كل وجه، الذي لا مثيل له، فكذلك كلامه كامل من كل وجه، لا مثيل له، فهذا وحده كافٍ في وصف القرآن، دال على مرتبته. السعدي:٧١٨.\nفي هذه الآية إخبار عن عظمة القرآن، بين ذلك.\nأَلَا لِلَّهِ ٱلدِّينُ ٱلۡخَالِصُۚ\nقال ابن العربي: \"هذه الآية دليل على وجوب النية الخالصة في كل عمل\". القرطبي:١٨/٢٤٦.\nما العمل القلبي المستفاد من الآية؟ وهل هو واجب؟\nإِنَّ ٱللَّهَ لَا يَهۡدِي مَنۡ هُوَ كَٰذِبٞ كَفَّارٞ ٣\nولا جرم أنه كلما توغّل العبد في الكذب على الله وفي الكفر به؛ ازداد غضب الله عليه، فازداد بُعد الهداية الإلاهية عنه؛ كما قال تعالى: ﴿كَيۡفَ يَهۡدِي ٱللَّهُ قَوۡمٗا كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ وَشَهِدُوٓاْ أَنَّ ٱلرَّسُولَ حَقّٞ وَجَآءَهُمُ ٱلۡبَيِّنَٰتُۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ﴾ [آل عمران:٨٦]. ابن عاشور:٢٣/٣٢٤.\nبيّن خطورة الكذب على الله تعالى من خلال الآية.\nلَّوۡ أَرَادَ ٱللَّهُ أَن يَتَّخِذَ وَلَدٗا لَّٱصۡطَفَىٰ مِمَّا يَخۡلُقُ مَا يَشَآءُۚ سُبۡحَٰنَهُۥۖ هُوَ ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ ٤\nنزه تعالى نفسه من اتخاذ الولد، ثم وصف نفسه بالواحد؛ لأن الوحدانية تنافي اتخاذ الولد؛ لأنه لو كان له ولد لكان من جنسه، ولا جنس له؛ لأنه واحد، ووصف نفسه بالقهار ليدل على نفي الشركاء والأنداد؛ لأن كل شيء مقهور تحت قهره تعالى؛ فكيف يكون شريكًا له. ابن جزي:٢/٢٦٣.\nفي ختم الآية بقوله: ﴿ٱلۡوَٰحِدُ ٱلۡقَهَّارُ﴾ مناسبةً لطيفةً لمضمون الآية، بينها."],[459,"§الزمر\nwords\nثَمَانِيَةَ أَزوَاجٍثَمَانِيَةَ أَنوَاعٍ ذُكُورًا وإِنَاثًا؛ مِنَ الإِبِلِ وَالبَقَرِ وَالضَّأنِ وَالمَعزِ.\nفِي ظُلُمَاتٍ ثَلاَثٍظُلمَةِ البَطنِ، وَالرَّحِمِ، وَالمَشِيمَةِ.\nفَأَنَّى تُصرَفُونَكَيفَ تَعدِلُونَ عَن عِبَادَتِهِ؟!\nخَوَّلَهُأَعطَاهُ وَمَنَحَهُ.\nقَانِتٌمُطِيعٌ خَاضِعٌ لِلهِ.\nيُوَفَّىيُعطَى وَافِيًا.\ndeeds\nبِرَّ أمك التي خلقك الله في بطنها.\nتصدق على مسكين؛ شكرًا لله على نعمه المتتابعة عليك.\nقم الليل، وادع الله: \"اللهم إني أرجو رحمتك، وأخشى عذابك، إن عذابك الجد بالكفار ملحق\".\nguid\nكن ممن يعرف ربه في الرخاء كما يعرفه في الشدة.\nرفع الله مكانة أهل العلم فكن منهم.\nكن من أهل الصبر؛ فإن أجرهم بغير حساب.\nrefl\nوَأَنزَلَ لَكُم مِّنَ ٱلۡأَنۡعَٰمِ ثَمَٰنِيَةَ أَزۡوَٰجٖۚ\nوهي التي ذكرها في سورة الأنعام: ﴿ثَمَٰنِيَةَ أَزۡوَٰجٖۖ مِّنَ ٱلضَّأۡنِ ٱثۡنَيۡنِ وَمِنَ ٱلۡمَعۡزِ ٱثۡنَيۡنِ﴾، ﴿وَمِنَ ٱلۡإِبِلِ ٱثۡنَيۡنِ وَمِنَ ٱلۡبَقَرِ ٱثۡنَيۡنِ﴾ [الأنعام: ١٤٣، ١٤٤]. وخصها بالذكر، مع أنه أنزل لمصالح عباده من البهائم غيرها؛ لكثرة نفعها، وعموم مصالحها، ولشرفها، ولاختصاصها بأشياء لا يصلح غيرها؛ كالأضحية، والهدي، والعقيقة، ووجوب الزكاة فيها، واختصاصها بالدية. السعدي:٧١٩.\nلماذا خص هذه الأزواج الثمانية دون غيرها من سائر البهائم؟\nيَخۡلُقُكُمۡ فِي بُطُونِ أُمَّهَٰتِكُمۡ خَلۡقٗا مِّنۢ بَعۡدِ خَلۡقٖ فِي ظُلُمَٰتٖ ثَلَٰثٖۚ\n﴿خَلۡقًا مِّنۢ بَعۡدِ خَلۡقٍ﴾ يعني: أن الإنسان يكون نطفة، ثم علقة، ثم مضغة، إلى أن يتم خلقه، ثم ينفخ فيه الروح. ابن جزي:٢/٢٦٤.\nبينت الآية ضعف المخلوق، وقدرة الخالق، وضح ذلك.\nيَخۡلُقُكُمۡ فِي بُطُونِ أُمَّهَٰتِكُمۡ خَلۡقٗا مِّنۢ بَعۡدِ خَلۡقٖ فِي ظُلُمَٰتٖ ثَلَٰثٖۚ\n﴿فِي ظُلُمَٰتٍ ثَلَٰثٍۚ﴾ أي: ظلمة البطن، وظلمة الرحم، وظلمة المشيمة. الجزائري:٤/٤٦٨.\nما الظلمات الثلاث المذكورة في الآية الكريمة؟\nذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ لَهُ ٱلۡمُلۡكُۖ\nووصفه بالربوبية تذكير لهم بنعمة الإِيجاد والإِمداد؛ وهو معنى الربوبية، وتوطئة للتسجيل عليهم بكفران نعمته الآتي في قوله: ﴿إِن تَكۡفُرُواْ فَإِنَّ ٱللَّهَ غَنِيٌّ عَنكُمۡۖ وَلَا يَرۡضَىٰ لِعِبَادِهِ ٱلۡكُفۡرَۖ﴾. ابن عاشور:٢٣/٣٣٦.\nما فائدة وصف الله تعالى بالربوبية في الآية الكريمة؟\nأَمَّنۡ هُوَ قَٰنِتٌ ءَانَآءَ ٱلَّيۡلِ سَاجِدٗا وَقَآئِمٗا يَحۡذَرُ ٱلۡأٓخِرَةَ وَيَرۡجُواْ رَحۡمَةَ رَبِّهِۦۗ\nوتخصيص الليل بقنوتهم؛ لأن العبادة بالليل أعون على تمحض القلب لذكر الله، وأبعد عن مداخلة الرياء، وأدل على إيثار عبادة الله على حظ النفس من الراحة والنوم؛ فإن الليل أدعى إلى طلب الراحة، فإذا آثر المرء العبادة فيه استنار قلبه بحب التقرب إلى الله؛ قال تعالى: ﴿إِنَّ نَاشِئَةَ ٱلَّيۡلِ هِيَ أَشَدُّ وَطۡـٔٗا وَأَقۡوَمُ قِيلًا﴾ [المزمل: ٦]. ابن عاشور:٢٣/٣٤٦.\nلماذا خص الليل بالعبادة في الآية الكريمة؟\nلِلَّذِينَ أَحۡسَنُواْ فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةٞۗ وَأَرۡضُ ٱللَّهِ وَٰسِعَةٌۗ\nالنص عام أنه كل من أحسن فله في الدنيا حسنة؛ فما بال من آمن في أرض يضطهد فيها ويمتهن لا يحصل له ذلك، دفع هذا الظن بقوله: ﴿وَأَرۡضُ ٱللَّهِ وَٰسِعَةٌۗ﴾... أخبر أن أرضه واسعة؛ فمهما منعتم من عبادته في موضع فهاجروا إلى غيرها. السعدي:٧٢١.\nلماذا ذكر سعة أرضه بعد ذكر أن لكل محسن حسنة في هذه الدنيا؟\nإِنَّمَا يُوَفَّى ٱلصَّٰبِرُونَ أَجۡرَهُم بِغَيۡرِ حِسَابٖ ١٠\nقال علي -رضي الله عنه-: \"كل مطيع يكال له كيلًا، ويوزن له وزنًا؛ إلا الصابرون، فإنه يُحثى لهم حثيًا\"، و يروى: \"يؤتي بأهل البلاء فلا يُنصب لهم ميزان، ولا ينشر لهم ديوان، ويُصب عليهم الأجر صبًا بغير حساب... حتى يتمنى أهل العافية في الدنيا أن أجسادهم تقرض بالمقاريض مما يذهب به أهل البلاء من الفضل\". البغوي:٤/٩.\nكيف يكون أجر الصابرين عند الله تعالى بغير حساب؟"],[460,"§الزمر\nwords\nظُلَلٌ مِنَ النَّارِأَطبَاقٌ مِن عَذَابِ النَّارِ كَهَيئَةِ الظُّلَلِ المَبنِيَّةِ.\nالطَّاغُوتَالمَعبُودَاتِ مِن دُونِ اللهِ؛ مِنَ الأَوثَانِ وَالشَّيَاطِينِ.\nوَأَنَابُوارَجَعُوا إِلَى اللهِ بِالتَّوبَةِ، وَالطَّاعَةِ.\nفَسَلَكَهُ يَنَابِيعَأَدخَلَهُ فِي عُيُونٍ وَمَجَارٍ.\nيَهِيجُيَيبَسُ.\nحُطَامًامُتَكَسِّرًا مُتَفَتِّتًا.\ndeeds\nتعاون مع أحد أفراد أسرتك على عمل صالح؛ رجاء أن تفوزوا جميعًا يوم القيامة.\nاستمع إلى آيات من كتاب الله، وطبق ما فيها.\nاستمع إلى محاضرة، أو كلمة في مسجد، وطبق ما فيها.\nguid\nالإخلاص في الدين والعبادة من صفات النبي الكريم -صلى الله عليه وسلم-.\nالإنسان العاقل يتذكر قبل المعصية العذاب العظيم.\nأشد الناس خسرانًا من خسر نفسه وأهله يوم القيامة.\nrefl\nقُلۡ إِنِّيٓ أُمِرۡتُ أَنۡ أَعۡبُدَ ٱللَّهَ مُخۡلِصٗا لَّهُ ٱلدِّينَ ١١ وَأُمِرۡتُ لِأَنۡ أَكُونَ أَوَّلَ ٱلۡمُسۡلِمِينَ ١٢\nفإن قيل: كيف عطف (أُمِرت) على (أُمِرت) والمعنى واحد؟ فالجواب: أن الأول أمر بالعبادة والإخلاص، والثاني أمر بالسبق إلى الإسلام، فهما معنيان اثنان. ابن جزي:٢/٢٦٦.\nفي تكرار فعل (أُمِرت) في الآيتين حث على أمرين؛ فما هما؟\nوَأُمِرۡتُ لِأَنۡ أَكُونَ أَوَّلَ ٱلۡمُسۡلِمِينَ ١٢\nلأني الداعي الهادي للخلق إلى ربهم، فيقتضي أني أول من ائتمر بما آمر به، وأول من أسلم، وهذا الأمر لا بد من إيقاعه من محمد -صلى الله عليه وسلم- وممن زعم أنه من أتباعه. السعدي:٧٢١.\nحث القرآن الكريم على قوة التمسك بالدين، بين ذلك من خلال الآية الكريمة.\nقُلۡ إِنَّ ٱلۡخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ وَأَهۡلِيهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ\nأي: تفارقوا؛ فلا التقاء لهم أبدًا، وسواء ذهب أهلوهم إلى الجنة وقد ذهبوا هم إلى النار، أو أن الجميع أسكنوا النار؛ ولكن لا اجتماع لهم ولا سرور. ابن كثير:٤/٤٩.\nلو دخل العصاة مع أهليهم النار يوم القيامة هل يكونون سعداء بهم؟\nٱلَّذِينَ يَسۡتَمِعُونَ ٱلۡقَوۡلَ فَيَتَّبِعُونَ أَحۡسَنَهُۥٓۚ\nقال ابن عباس: \"هو الرجل يسمع الحسن والقبيح، فيتحدث بالحسن، وينكف عن القبيح، فلا يتحدث به\"، وقيل: \"يستمعون القرآن وغيره؛ فيتبعون القرآن\". القرطبي:١٨/٢٦٠.\nكيف يكون استماع القول واتباع أحسنه؟\nٱلَّذِينَ يَسۡتَمِعُونَ ٱلۡقَوۡلَ فَيَتَّبِعُونَ أَحۡسَنَهُۥٓۚ أُوْلَٰٓئِكَ ٱلَّذِينَ هَدَىٰهُمُ ٱللَّهُۖ وَأُوْلَٰٓئِكَ هُمۡ أُوْلُواْ ٱلۡأَلۡبَٰبِ ١٨\nهذا جنس يشمل كل قول؛ فهم يستمعون جنس القول ليميزوا بين ما ينبغي إيثاره مما ينبغي اجتنابه، فلهذا من حزمهم وعقلهم أنهم يتبعون أحسنه، وأحسنه على الإطلاق كلام الله وكلام رسوله؛ كما قال في هذه السورة: ﴿ٱللَّهُ نَزَّلَ أَحۡسَنَ ٱلۡحَدِيثِ كِتَٰبًا مُّتَشَٰبِهًا﴾... فإن الذي لا يميز بين الأقوال -حسنها وقبيحها-؛ ليس من أهل العقول الصحيحة، أو الذي يميز لكن غلبت شهوته عقله، فبقي عقله تابعًا لشهوته، فلم يؤثر الأحسن؛ كان ناقص العقل. السعدي:٧٢٢.\nكيف تحكم على شخص بأنه صاحب عقل راجح ومتزن؟\nٱلَّذِينَ يَسۡتَمِعُونَ ٱلۡقَوۡلَ فَيَتَّبِعُونَ أَحۡسَنَهُۥٓۚ أُوْلَٰٓئِكَ ٱلَّذِينَ هَدَىٰهُمُ ٱللَّهُۖ وَأُوْلَٰٓئِكَ هُمۡ أُوْلُواْ ٱلۡأَلۡبَٰبِ ١٨\nيستمعون القرآن فيتبعون بأعمالهم أحسنه؛ من العفو الذي هو أحسن من الانتصار، وشبه ذلك. ابن جزي:٢/٢٦٧.\nمن خلال ما ورد في تفسير هذه الآية، كيف يتبع الإنسان أحسن القول؟\nأَفَمَنۡ حَقَّ عَلَيۡهِ كَلِمَةُ ٱلۡعَذَابِ أَفَأَنتَ تُنقِذُ مَن فِي ٱلنَّارِ ١٩\nاجتلب فعل الإِنقاذ هنا تشبيهًا لحال النبي -صلى الله عليه وسلم- في حرصه على هديهم، وحالِهم في انغماسهم في موجبات وعيدهم بحال من يحاول إنقاذ ساقط في النار قد أحاطت النار بجوانبه. ابن عاشور:٢٣/٣٧١.\nبيّن حرص النبي -صلى الله عليه وسلم- على هداية الخلق من خلال الآية الكريمة."],[461,"§الزمر\nwords\nمَثَانِيَتُثَنَّى وَتُكَرَّرُ فِيهِ الأَحكَامُ وَالقَصَصُ وَالحُجَجُ.\nتَقشَعِرُّتَضطَرِبُ، وَتَرتَعِدُ.\nتَلِينُتَسكُنُ، وَتَطمَئِنُّ.\nعِوَجٍاضطِرَابٍ، وَلَبسٍ.\nمُتَشَاكِسُونَمُتَنَازِعُونَ.\ndeeds\nقل أذكار الصباح والمساء؛ فإنها من أسباب انشراح الصدر.\nاقرأ كتيبًا عن أسباب الخشوع عند قراءة القرآن الكريم.\nاحرص اليوم أكثر على تدبر القرآن الكريم.\nguid\nاعلم أن الهداية بيد الله تعالى؛ لا يملكها أحد غيره، فاطلبها منه كل حين.\nمن لم يتقِ معصية الله في الدنيا فلن يقي وجهه سوء العذاب يوم القيامة.\nتيقن أن مآل الجميع إلى الموت، وإذا كان الأمر كذلك، فكن مستعدًا لذلك اليوم.\nrefl\nأَفَمَن شَرَحَ ٱللَّهُ صَدۡرَهُۥ لِلۡإِسۡلَٰمِ فَهُوَ عَلَىٰ نُورٖ مِّن رَّبِّهِۦۚ\nإيثار كلمة (شرح) للدلالة على قبول الإِسلام؛ لأن تعاليم الإِسلام وأخلاقه وآدابه تكسب المسلم فرحًا بحاله، ومسرّة برضى ربه، واستخفافًا للمصائب والكوارث؛ لجزمه بأنه على حق في أمره، وأنه مثاب على ضره، وأنه راج رحمة ربه في الدنيا والآخرة، ولعدم مخالطة الشك والحيرة ضميره. ابن عاشور:٢٣/٣٨٠.\nبيّن مناسبة كلمة (شرح) للدلالة على قبول الإسلام.\nفَوَيۡلٞ لِّلۡقَٰسِيَةِ قُلُوبُهُم مِّن ذِكۡرِ ٱللَّهِۚ أُوْلَٰٓئِكَ فِي ضَلَٰلٖ مُّبِينٍ ٢٢\nقال مالك بن دينار: \"ما ضُرِب عبد بعقوبة أعظم من قسوة قلب، وما غضب الله -عز وجل- على قوم إلا نزع منهم الرحمة\". البغوي:٤/١٢.\nما أعظم عقوبة تنزل بالعبد؟\nيَٰٓأَيُّهَا ٱلنَّبِيُّ جَٰهِدِ ٱلۡكُفَّارَ وَٱلۡمُنَٰفِقِينَ\nفإن الغلظة عليهم من اللين لله، كما أن اللين لأهل الله من خشية الله. وقد أمره سبحانه باللين لهم في أول الأمر لإزالة أعذارهم وبيان إصرارهم؛ فلما بلغ الرفق أقصى مداه جازه إلى الغلظة وتعداه. البقاعي: ٢٠/٢٠٦.\nمتى يؤمر المرء بالغلظة على الكفار والمنافقين؟\nٱللَّهُ نَزَّلَ أَحۡسَنَ ٱلۡحَدِيثِ\nومعنى كون القرآن أحسن الحديث، أنه أفضل الأخبار؛ لأنه اشتمل على أفضل ما تشتمل عليه الأخبار؛ من المعاني النافعة والجامعة لأصول الإِيمان والتشريع والاستدلال، والتنبيه على عظم العوالم والكائنات، وعجائب تكوين الإِنسان، والعقل، وبثّ الآداب، واستدعاء العقول للنظر والاستدلال الحق، ومن فصاحة ألفاظه وبلاغة معانيه البالغَين حدّ الإعجاز. ابن عاشور:٢٣/٣٨٥.\nما وجه تسمية القرآن أحسن الحديث باختصار؟\nٱللَّهُ نَزَّلَ أَحۡسَنَ ٱلۡحَدِيثِ كِتَٰبٗا مُّتَشَٰبِهٗا مَّثَانِيَ\nأي: تثنى فيه القصص والأحكام، والوعد والوعيد، وصفات أهل الخير وصفات أهل الشر، وتثنى فيه أسماء الله وصفاته... وأن تلك المعاني للقلوب بمنزلة الماء لسقي الأشجار، فكما أن الأشجار كلما بَعُد عهدها بسقي الماء نقصت، بل ربما تلفت، وكلما تكرر سقيها حسنت وأثمرت أنواع الثمار النافعة؛ فكذلك القلب يحتاج دائمًا إلى تكرُّرِ معاني كلام الله تعالى عليه... وهكذا ينبغي للقارئ للقرآن المتدبر لمعانيه أن لا يدع التدبر في جميع المواضع منه؛ فإنه يحصل له بسبب ذلك خير كثير ونفع غزير. السعدي:٧٢٣.\nبعض المعاني قد تتكرر في القرآن في مواضع كثيرة؛ فما الحكمة من هذا التكرار؟\nتَقۡشَعِرُّ مِنۡهُ جُلُودُ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُمۡ ثُمَّ تَلِينُ جُلُودُهُمۡ وَقُلُوبُهُمۡ إِلَىٰ ذِكۡرِ ٱللَّهِۚ ذَٰلِكَ هُدَى ٱللَّهِ يَهۡدِي بِهِۦ مَن يَشَآءُۚ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٍ ٢٣\nفإن قيل: لم ذكر الجلود أولًا وحدها، ثم ذكر القلوب بعد ذلك معها؟ فالجواب: أنه لمَّا قال أولًا: (تقشعر) ذكر الجلود وحدها؛ لأن القشعريرة من وصف الجلود لا من وصف غيرها، ولما قال ثانيًا: (تلين) ذكر الجلود والقلوب؛ لأن اللين توصف به الجلود والقلوب... فاقشعرت أولًا من الخوف، ثم لانت بالرجاء. ابن جزي:٢/٢٦٨.\nلم ذكرت الجلود أولًا وحدها، ثم ذكرت الجلود والقلوب بعدها معًا؟\nوَضَرَبَ ٱللَّهُ مَثَلٗا لِّلَّذِينَ ءَامَنُواْ ٱمۡرَأَتَ فِرۡعَوۡنَ إِذۡ قَالَتۡ رَبِّ ٱبۡنِ لِي عِندَكَ بَيۡتٗا فِي ٱلۡجَنَّةِ وَنَجِّنِي مِن فِرۡعَوۡنَ وَعَمَلِهِۦ وَنَجِّنِي مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ ١١\nووجه المثل: أن اتصال المؤمن بالكافر لا يضره شيئًا إذا فارقه في كفره وعمله؛ فمعصية الغير لا تضر المؤمن المطيع شيئًا في الآخرة، وإن تضرر بها في الدنيا بسبب العقوبة التي تحل بأهل الأرض إذا أضاعوا أمر الله، فتأتي عامة؛ فلم يضر امرأة فرعون اتصالها به وهو من أكفر الكافرين. ابن القيم: ٣/١٧٠.\nماذا يجب على المؤمن إذا ابتلي بعلاقة مع كافر؟\nأَفَمَن يَتَّقِي بِوَجۡهِهِۦ سُوٓءَ ٱلۡعَذَابِ يَوۡمَ ٱلۡقِيَٰمَةِۚ\nجاءه العذاب العظيم، فجعل يتقي بوجهه الذي هو أشرف الأعضاء وأدنى شيء من العذاب يؤثر فيه، فهو يتقي فيه سوء العذاب؛ لأنه قد غُلَّت يداه ورجلاه. السعدي:٧٢٣.\nما السبب في اتقاء أهل النار العذاب بوجوههم؟\nوَلَقَدۡ ضَرَبۡنَا لِلنَّاسِ فِي هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلٖ لَّعَلَّهُمۡ يَتَذَكَّرُونَ ٢٧\nوخُصّت أمثال القرآن بالذكر من بين مزايا القرآن؛ لأجل لَفت بصائرهم للتدبر في ناحية عظيمة من نواحي إعجازه؛ وهي بلاغة أمثاله؛ فإن بلغاءهم كانوا يتنافسون في جَودة الأمثال. ابن عاشور:٢٣/٣٩٧.\nلمَ خصت أمثال القرآن بالذكر؟"],[462,"§الزمر\nwords\nبِالصِّدقِبِالحَقِّ.\nمَثوىًمَأوىً وَمَسكَنٌ.\nحَسبِيَكَافِينِي.\nمَكَانَتِكُمحَالَتِكُمُ الَّتِي رَضِيتُمُوهَا لأَنفُسِكُم.\nيُخزِيهِيُذِلُّهُ، وَيُهِينُهُ.\ndeeds\nاحرص منذ اليوم على قول الصدق في جدك ومزحك.\nقل: \"اللهم يا مقلب القلوب؛ ثبت قلبي على دينك\".\nقل هذا الدعاء: \"حسبي الله لا إله إلا هو، عليه توكلت وهو رب العرش العظيم\".\nguid\nالصدق له أهمية كبرى في تقوى الله -عز وجل-؛ فكن من الصادقين مع نفسك ومع غيرك.\nمتى كنت عبدًا لله حقًا حقق الله تعالى لك كفايتك وحفظك.\nمهما واجهت من المثبطين فليكن خوفك من الله أكبر.\nrefl\n۞فَمَنۡ أَظۡلَمُ مِمَّن كَذَبَ عَلَى ٱللَّهِ وَكَذَّبَ بِٱلصِّدۡقِ إِذۡ جَآءَهُۥٓۚ أَلَيۡسَ فِي جَهَنَّمَ مَثۡوٗى لِّلۡكَٰفِرِينَ ٣٢\nفإنهم أتوا أصنافًا من الظلم العظيم: ظلم الاعتداء على حرمة الرب بالكذب في صفاته؛ إذ زعموا أن له شركاء في الربوبية، والكذب عليه بادعاء أنه أمَرهم بما هم عليه من الباطل، وظُلم الرسول بتكذيبه، وظلم القرآن بنسبته إلى الباطل، وظلم المؤمنين بالأذى، وظلم حقائق العالم بقلبها وإفسادها، وظلم أنفسهم بإقحامها في العذاب الخالد. ابن عاشور:٢٤/ ٥.\nاذكر بعض أصناف الظلم التي استحق عليها المشركون وصف أظلم الخلق.\nوَٱلَّذِي جَآءَ بِٱلصِّدۡقِ وَصَدَّقَ بِهِۦٓ أُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ ٣٣\nفإن جميع خصال التقوى ترجع إلى الصدق بالحق والتصديق به. السعدي:٧٢٤.\nما علاقة التقوى بالصدق بالحق والتصديق به؟\nأَلَيۡسَ ٱللَّهُ بِكَافٍ عَبۡدَهُۥۖ وَيُخَوِّفُونَكَ بِٱلَّذِينَ مِن دُونِهِۦۚ\nوفي استحضار الرسول بوصف العبودية، وإضافته إلى ضمير الجلالة معنى عظيم من تشريفه بهذه الإِضافة، وتحقيق أنه غير مُسلمِه إلى أعدائه. ابن عاشور:٢٤/١٣.\nبيّن تشريف الله لنبيه -صلى الله عليه وسلم- من الآية الكريمة.\nأَلَيۡسَ ٱللَّهُ بِكَافٍ عَبۡدَهُۥۖ وَيُخَوِّفُونَكَ بِٱلَّذِينَ مِن دُونِهِۦۚ\nوقوله تعالى: ﴿أَلَيۡسَ ٱللَّهُ بِكَافٍ عَبۡدَهُۥۖ﴾ تقوية لنفس النبي -عليه السلام-؛ لأن كفار قريش كانت خوَّفته من الأصنام، وقالوا: يا محمد أنت تسبها ونخاف أن تصيبك بجنون أو علة؛ فنزلت الآية في ذلك. ابن عطية:٤/٥٣٢.\nما موقف المؤمن حينما يخوَّف بالمخلوقين؟ وضّح ذلك من الآية.\nأَلَيۡسَ ٱللَّهُ بِعَزِيزٖ ذِي ٱنتِقَامٖ ٣٧\nفإذا كانوا يقرّون لله بالوصفين المذكورين فما عليهم إلا أن يعلموا أنّه كافٍ عبده بعزته، فلا يقدر أحد على إصابة عبده بسوء، وبانتقامه من الذين يبتغون لعبده الأذى. ابن عاشور:٢٤/١٥.\nما مناسبة ختم الآية الكريمة بالصفتين ﴿بِعَزِيزٍ ذِي ٱنتِقَامٍ﴾؟\nقُلۡ يَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَٰمِلٞۖ فَسَوۡفَ تَعۡلَمُونَ ٣٩ مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَيَحِلُّ عَلَيۡهِ عَذَابٞ مُّقِيمٌ ٤٠\nلما أبلغهم الله من الموعظة أقصى مَبلغ، ونصب لهم من الحجج أسطع حجة، وثبَّت رسوله -صلى الله عليه وسلم- أرسخ تثبيت، لا جَرَمَ أمر رسوله -صلى الله عليه وسلم- بأن يوادعهم موادعة مستقرِب النصر، ويواعدهم ما أُعد لهم من خسر. ابن عاشور:٢٤/١٩.\nما مناسبة الآيات الكريمة لمَّا قبلها؟\nمَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَيَحِلُّ عَلَيۡهِ عَذَابٞ مُّقِيمٌ ٤٠\n﴿عَذَابٌ يُخۡزِيهِ﴾ أي: يذله، ويكسر أنفه بالقتل والأسر والجوع والقحط، وقد أصاب المشركين هذا في مكة وبدر. وقوله: ﴿وَيَحِلُّ عَلَيۡهِ عَذَابٌ مُّقِيمٌ﴾ وهو عذاب النار في الآخرة، نعوذ بالله من العذابين: عذاب الخزي في الحياة الدنيا، وعذاب النار في الدار الآخرة. الجزائري:٤/٤٩٠.\nما الفرق بين عذاب الخزي والعذاب المقيم؟"],[463,"§الزمر\nwords\nيَتَوَفَّىيقبِضُ.\nاشْمَأَزَّتنفَرَت.\nفَاطِرَخالِقَ ومُبدِعَ.\nالغَيْبِ والشَّهَادَةِالسِّرِّ والعَلانِيَةِ.\nيَحْتَسِبُونَيظُنُّونَ ويَتوَقَّعونَ.\ndeeds\nقل: \"اللهم أسلمت نفسي إليك، وفوضت أمري إليك، وألجأت ظهري إليك؛ رغبةً ورهبةً إليك، لا ملجأ ولا مَنجى منك إلا إليك، آمنت بكتابك الذي أنزلت، وبنبيك الذي أرسلت\".\nاذكر الله تعالى بمأثورات متنوعة من الذكر.\nحدد عملًا أنت متردد في صحته، واسأل أحد العلماء عن حكمه.\nguid\nتفكُّر ساعة خير من قيام ليلة بلا تفكر، كما جاء عن بعض السلف.\nالشفاعة كلها بيد الله تعالى؛ فاطلبها منه سبحانه.\nاحرص على تفقد عملك؛ من إخلاص النية، وموافته للسنة.\nrefl\nٱللَّهُ يَتَوَفَّى ٱلۡأَنفُسَ حِينَ مَوۡتِهَا\nإخباره أنه يتوفى الأنفس وإضافة الفعل إلى نفسه لا ينافـي أنه قد وكّل بذلك ملك الموت وأعوانه... لأنه تعالى يضيف الأشياء إلى نفسه باعتبار أنه الخالق المدبر، ويضيفها إلى أسبابها باعتبار أن من سننه تعالى وحكمته أن جعل لكل أمر من الأمور سببًا. السعدي:٧٢٥.\nكيف تجمع بين كون الله يتوفى الأنفس، وكون ملك الموت هو الذي يتوفاها؟\nإِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ ٤٢\nأي: لَدلالات على قدرته؛ حيث لم يغلط في إمساك ما يمسك من الأرواح، وإرسال ما يرسل منها، قال مقاتل: \"لعلامات لقوم يتفكرون في أمر البعث\"، يعني: أن توفي نفس النائم وإرسالها بعد التوفي دليل على البعث. البغوي:٤/١٩.\nبيّن وجه دلالة إمساك الأنفس ثم إرسالها في النوم على البعث.\nأَمِ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ شُفَعَآءَۚ قُلۡ أَوَلَوۡ كَانُواْ لَا يَمۡلِكُونَ شَيۡـٔٗا وَلَا يَعۡقِلُونَ ٤٣\nولما كانت الشفاعة أمرًا معنويًا؛ كان معنى ملكها: تحصيل إجابتها. والكلام تهكم؛ إذ كيف يشفع من لا يعقل؟! فإنه لعدم عقله لا يتصور خُطُورُ معنى الشفاعة عنده، فضلًا عن أن تتوجه إرادته إلى الاستشفاع؛ فاتخاذهم شفعاء من الحماقة. ابن عاشور:٢٤/٢٧.\nكيف كان التهكم بالمشركين لاتخاذهم الأصنام شفعاء؟\nقُل لِّلَّهِ ٱلشَّفَٰعَةُ جَمِيعٗاۖ لَّهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ\nنصٌّ في أن الشفاعة لله وحده؛ كما قال: ﴿مَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦ﴾ [البقرة:٢٥٥]؛ فلا شافع إلا من شفاعته. القرطبي: ١٨/٢٨٩.\nهل يملك أحد غير الله تعالى الشفاعة؟\nوَإِذَا ذُكِرَ ٱللَّهُ وَحۡدَهُ ٱشۡمَأَزَّتۡ قُلُوبُ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِۖ\nمعناها: أن الكفار يكرهون توحيد الله، ويحبون الإشراك به، ومعنى (اشمأزت): انقبضت من شدة الكراهية. ابن جزي:٢/٢٧١.\nكيف تستدل بهذه الآية على أن التوحيد شامل لأعمال القلوب؟\nقُلِ ٱللَّهُمَّ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ عَٰلِمَ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ أَنتَ تَحۡكُمُ بَيۡنَ عِبَادِكَ فِي مَا كَانُواْ فِيهِ يَخۡتَلِفُونَ ٤٦\nووصف ﴿فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ﴾ مشعر بصفة القدرة، وتقديمُه قبل وصف العِلم؛ لأن شعور الناس بقدرته سابق على شعورهم بعلمه، ولأن القدرة أشدّ مناسبة لطلب الحكم؛ لأن الحكم إلزام وقهر، فهو من آثار القدرة مباشرةً. ابن عاشور:٢٤/٣١.\nما مناسبة الآيات الكريمة لما قبلها؟\nوَبَدَا لَهُم مِّنَ ٱللَّهِ مَا لَمۡ يَكُونُواْ يَحۡتَسِبُونَ ٤٧\nمجاهد قال: \"عملوا أعمالًا توهموا أنها حسنات، فإذا هي سيئات\". ويجوز أن يكونوا توهموا أنه يغفر لهم من غير توبة. ﴿وَبَدَا لَهُم مِّنَ ٱللَّهِ مَا لَمۡ يَكُونُواْ يَحۡتَسِبُونَ﴾ من دخول النار. وقال سفيان الثوري في هذه الآية: \"ويل لأهل الرياء، ويل لأهل الرياء؛ هذه آيتهم وقصتهم\". وقال عكرمة ابن عمار: جزِع محمد بن المنكدر عند موته جزعًا شديدًا، فقيل له: ما هذا الجزع؟ قال: \"أخاف آية من كتاب الله: ﴿وَبَدَا لَهُم مِّنَ ٱللَّهِ مَا لَمۡ يَكُونُواْ يَحۡتَسِبُونَ﴾، فأنا أخشى أن يبدو لي ما لم أكن أحتسب\". القرطبي:١٨/٢٨٩.\nهل يمكن أن تجد ما تظنه حسنات يوم القيامة سيئات؟"],[464,"§الزمر\nwords\nوَحَاقَأَحَاطَ بِهِم مِن كُلِّ جَانِبٍ.\nخَوَّلنَاهُأَعطَينَاهُ، وَمَنَحنَاهُ.\nوَأَنِيبُواارجِعُوا إِلَى اللهِ بِالتَّوبَةِ، وَالطَّاعَةِ.\nفَرَّطتُضَيَّعتُ.\nجَنبِ اللهِطَاعَتِهِ، وَحَقِّهِ.\ndeeds\nتذكّر ثلاثًا من أكبر نعم الله تعالى عليك، ثم اشكر الله تعالى عليها.\nقل: \"اللهم اغفر لي ذنبي كله، دِقَّهُ وجِلّه، أوله وآخره، علانيته وسره\".\nسَلِ الله تعالى أن يجعل ما رزقك من نعم الدنيا سببًا لتواضعك والقرب من ربك، واستعذ بالله من فتنتها.\nguid\nاحذر من ابتلاء الله لك بالنعم؛ فكم من منعم عليه مفتون مستدرج وهو لا يدري.\nكن راضيًا عن الله في جميع قضائه؛ فهو سبحانه يبسط ويقبض لمن يشاء.\nإذا كانت البشارة بالمغفرة والرحمة للمسرف في الذنوب؛ فهي لغيره من باب أولى، فبادر بالتوبة.\nrefl\nوَبَدَا لَهُمۡ سَيِّـَٔاتُ مَا كَسَبُواْ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ٤٨\nوأوثر فعل (كسبوا) على فعل (عملوا)؛ لِقطع تبرمهم من العذاب بتسجيل أنهم اكتسبوا أسبابه بأنفسهم؛ كما تقدم آنفًا في قوله: ﴿وَقِيلَ لِلظَّٰلِمِينَ ذُوقُواْ مَا كُنتُمۡ تَكۡسِبُونَ﴾ [الزمر: ٢٤] دون: (تعملون). ابن عاشور:٢٤/٣٤.\nلماذا قال (كسبوا) ولم يقل: \"عملوا\"؟\nفَإِذَا مَسَّ ٱلۡإِنسَٰنَ ضُرّٞ دَعَانَا\nفي هذه الآية بيان حقيقة، وهي: أن كفار قريش كانوا يؤمنون بالله ربًا؛ فهم أفضل من كفار البلاشفة الشيوعيين الذين لا يؤمنون بالله تعالى، كما أن كفار قريش أحسن حالًا من بعض جهال المسلمين اليوم؛ إذ يخلصون الدعاء لله في الشدة، وجهال المسلمين يشركون في الرخاء والشدة معًا؛ وذلك بدعائهم الأولياء والأموات، والاستغاثة بهم في كل حال. الجزائري:٤/٤٩٨.\nلماذا كان كفار قريش أحسن حالًا من بعض جهال المسلمين اليوم؟\nقَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلۡمِۢ\nيحتمل وجهين؛ أحدهما -وهو الأظهر-: أن يريد على علم مني بالمكاسب والمنافع، والآخر: على علم الله باستحقاقي لذلك. ابن جزي:٢/٢٧١.\nفي الآية بيان غرور صاحب المال بنفسه، بين ذلك.\nثُمَّ إِذَا خَوَّلۡنَٰهُ نِعۡمَةٗ مِّنَّا قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلۡمِۢ بَلۡ هِيَ فِتۡنَةٞ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ٤٩\nأي: على علم من الله أني له أهل، وقال مقاتل: \"على خير عَلِمَه الله عندي\"... ﴿بَلۡ هِيَ فِتۡنَةٌ﴾ يعني: تلك النعمة فتنة استدراج من الله تعالى وامتحان وبلية. البغوي:٤/٢١.\nهل كل رزقٍ ونعمةٍ يُعد خيرًا للإنسان؟ بَيِّن ذلك من خلال الآية.\nبَلۡ هِيَ فِتۡنَةٞ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ٤٩\n﴿وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ﴾ فلذلك يعدون الفتنة منحة، ويشتبه عليهم الخير المحض بما قد يكون سببًا للخير أو للشر. السعدي:٧٢٧.\nما خطورة وجود النعمة على الإنسان الجاهل والغافل؟\nأَوَ لَمۡ يَعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ ٥٢\nأي: بسط الرزق وقبضه عائد إلى الحكمة والرحمة، وأنه أعلم بحال عبيده؛ فقد يضيّق عليهم الرزق لطفًا بهم؛ لأنه لو بسطه لبغوا في الأرض؛ فيكون تعالى مراعيًا في ذلك صلاح دينهم الذي هو مادة سعادتهم وفلاحهم. السعدي:٧٢٧.\nكيف تكون قلة الرزق سببًا من أسباب لطف الله بعباده ورحمته بهم؟\n۞قُلۡ يَٰعِبَادِيَ ٱلَّذِينَ أَسۡرَفُواْ عَلَىٰٓ أَنفُسِهِمۡ لَا تَقۡنَطُواْ مِن رَّحۡمَةِ ٱللَّهِۚ إِنَّ ٱللَّهَ يَغۡفِرُ ٱلذُّنُوبَ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ٥٣\nأُطنبت آيات الوعيد بأفنانها السابقة إطنابًا يبلغ من نفوس سامعيها أيَّ مبلغ من الرعب والخوف، على رغم تظاهرهم بقلة الاهتمام بها، وقد يبلغ بهم وقعها مبلغَ اليأس من سَعيٍ ينجيهم من وعيدها؛ فأعقبها الله ببعث الرجاء في نفوسهم، للخروج إلى ساحل النجاة إذا أرادوها؛ على عادة هذا الكتاب المجيد من مداواة النفوس بمزيج الترغيب والترهيب. ابن عاشور:٢٤/٣٩.\nما مناسبة الآية لما سبقها؟"],[465,"§الزمر\nwords\nكَرَّةًرَجعَةً.\nبِمَفَازَتِهِمبِفَوزِهِم وَظَفَرِهِم بِالمَطلُوبِ.\nمَقَالِيدُمَفَاتِيحُ الخَزَائِنِ.\nلَيَحبَطَنَّلَيَبطُلَنَّ.\nقَبضَتُهُفِي قَبضَةِ يَدِهِ.\nمَطوِيَّاتٌيَطوِيهَا وَيَلُفُّهَا بِيَدِهِ.\ndeeds\nاحمد الله تعالى واشكره على نعمه التي من أجلِّها نعمة الإسلام.\nالشكر سبب لزوال العُجب من الأعمال الصالحة، فأكثر هذا اليوم من شكر الله تعالى على توفيقك للأعمال الصالحة.\nاكتب رسالة يسيرة تبين فيها مظاهر عظمة الله.\nguid\nاحذر من داء الكبر؛ فأهله في صغار يوم القيامة.\nالزم التقوى؛ فهي سبيل النجاة.\nمن أسباب الشرك الجهل، فاعمل على تعليم نفسك وتسليحها بالعلم الشرعي قدر الإمكان.\nrefl\nأَوۡ تَقُولَ لَوۡ أَنَّ ٱللَّهَ هَدَىٰنِي لَكُنتُ مِنَ ٱلۡمُتَّقِينَ ٥٧ أَوۡ تَقُولَ حِينَ تَرَى ٱلۡعَذَابَ لَوۡ أَنَّ لِي كَرَّةٗ فَأَكُونَ مِنَ ٱلۡمُحۡسِنِينَ ٥٨\nوقد حُكي كلام النفس في ذلك الموقف على ترتيبه الطبيعي في جَوَلانه في الخاطر؛ بالابتداء بالتحسر على ما أوقعت فيه نفسها، ثم بالاعتذار والتنصل؛ طمعًا أن ينجيها ذلك، ثم بتمنيّ أن تعود إلى الدنيا؛ لتعمل الإِحسان؛ كقوله تعالى: ﴿قَالَ رَبِّ ٱرۡجِعُونِ * لَعَلِّيٓ أَعۡمَلُ صَٰلِحٗا فِيمَا تَرَكۡتُ﴾ [المؤمنون: ٩٩- ١٠٠]؛ فهذا الترتيب في النظم هو أحكم ترتيب. ابن عاشور:٢٤/٤٧\nبيّن تناسب الآيات الكريمة في حكايتها كلام النفس يوم القيامة.\nوَيَوۡمَ ٱلۡقِيَٰمَةِ تَرَى ٱلَّذِينَ كَذَبُواْ عَلَى ٱللَّهِ وُجُوهُهُم مُّسۡوَدَّةٌۚ أَلَيۡسَ فِي جَهَنَّمَ مَثۡوٗى لِّلۡمُتَكَبِّرِينَ ٦٠\nوفي وصفهم بالمتكبرين إيماء إلى أن عقابهم بتسويد وجوههم كان مناسبًا لكبريائهم؛ لأن المتكبر إذا كان سيِّئ الوجه انكسرت كبرياؤه؛ لأن الكبرياء تضعف بمقدار شعور صاحبها بمعرفة الناس نقائصه. ابن عاشور:٢٤/٥١.\nما الحكمة في اسوداد وجوه المتكبرين يوم القيامة؟\nوَيُنَجِّي ٱللَّهُ ٱلَّذِينَ ٱتَّقَوۡاْ بِمَفَازَتِهِمۡ لَا يَمَسُّهُمُ ٱلسُّوٓءُ وَلَا هُمۡ يَحۡزَنُونَ ٦١\nأي: ﴿وَيُنَجِّي ٱللَّهُ ٱلَّذِينَ ٱتَّقَوۡاْ﴾ من جهنم؛ لأنهم ليسوا بمتكبرين، وهذا إيذان بأن التقوى تنافي التكبر؛ لأن التقوى كمال الخُلق الشرعي، وتقتضي اجتناب المنهيات، وامتثال الأمر في الظاهر والباطن، والكبر مرض قلبي باطني. ابن عاشور:٢٤/٥٢.\nما فائدة ذكر المتقين بعد ذكر المتكبرين؟\nٱللَّهُ خَٰلِقُ كُلِّ شَيۡءٖۖ\nهذه العبارة وما أشبهها مما هو كثير في القرآن تدل على أن جميع الأشياء غير الله مخلوقة؛ ففيها رد على كل من قال بقدم بعض المخلوقات؛ كالفلاسفة القائلين بقدم الأرض والسماوات، وكالقائلين بقدم الأرواح، ونحو ذلك من أقوال أهل الباطل المتضمنة تعطيل الخالق عن خلقه. السعدي:٧٢٨.\nكيف ترد على من قال بِقِدَم بعض المخلوقات؟ وما وجه الفساد في ذلك؟\nقُلۡ أَفَغَيۡرَ ٱللَّهِ تَأۡمُرُوٓنِّيٓ أَعۡبُدُ أَيُّهَا ٱلۡجَٰهِلُونَ ٦٤\nأي: هذا الأمر صدر من جهلكم، وإلا فلو كان لكم علم بأن الله تعالى الكامل من جميع الوجوه، مسدي جميع النعم، هو المستحق للعبادة، دون من كان ناقصًا من كل وجه، لا ينفع ولا يضر، لم تأمروني بذلك. السعدي:٧٢٩.\nما وجه وصف المشركين بالجهل؟\nبَلِ ٱللَّهَ فَٱعۡبُدۡ وَكُن مِّنَ ٱلشَّٰكِرِينَ ٦٦\n﴿وَكُن مِّنَ ٱلشَّٰكِرِينَ﴾ لله على توفيق الله تعالى؛ فكما أنه تعالى يُشكَرُ على النعم الدنيوية؛ كصحة الجسم وعافيته وحصول الرزق وغير ذلك، كذلك يُشكر ويُثنى عليه بالنعم الدينية؛ كالتوفيق للإخلاص والتقوى، بل نِعَم الدين هي النعم على الحقيقة. السعدي:٧٢٩.\nما وجه ختم الآية بقوله تعالى: ﴿وَكُن مِّنَ ٱلشَّٰكِرِينَ﴾؟\nبَلِ ٱللَّهَ فَٱعۡبُدۡ وَكُن مِّنَ ٱلشَّٰكِرِينَ ٦٦\nوفي تدبر أن النعم الدينية من الله تعالى، والشكر لله عليها سلامة من آفة العجب التي تعرض لكثير من العاملين بسبب جهلهم، وإلا فلو عرف العبد حقيقة الحال لم يعجب بنعمة تستحق عليه زيادة الشكر. السعدي:٧٢٩.\nفي هذه الآية توجيهٌ لإزالة الغرور والعجب الذي يعرض لبعض من يعمل الصالحات، بيِّن وجه ذلك."],[466,"§الزمر\nwords\nوَنُفِخَأَيِ: النَّفخَةُ الأُولَى الَّتِي يَمُوتُ بِهَا الخَلقُ؛ وَهِيَ نَفخَةُ الصَّعقِ.\nفَصَعِقَمَاتَ.\nزُمَرًاجَمَاعَاتٍ.\nفَبِئسَقَبُحَ.\nطِبتُمطَهُرتُم مِن دَنَسِ المَعَاصِي.\nنَتَبَوَّأُنَنزِلُ.\ndeeds\nأحسن اليوم قيامك بين يدي الله في صلاتك؛ ليهون عليك القيام بين يديه في الآخرة.\nاعمل اليوم عملًا يعينك على إزالة الكبر من نفسك؛ كمجالسة الفقراء والعمال، أو الأكل معهم، أو دعوتهم إلى منزلك.\nاعمل اليوم عبادات متنوعة؛ كالصلاة، والصيام، والصدقة؛ لعلك تدخل من أبواب الجنة التي خُصصت لهذه الأعمال.\nguid\nيوفى العبد كل عمل عمله يوم القيامة.\nاحذر من الإعراض عن داعي الخير، وترك الاستجابة له.\nكن طيب الباطن والظاهر، طيب المطعم والملبس؛ ليقال لك يوم القيامة.\nrefl\nوَأَشۡرَقَتِ ٱلۡأَرۡضُ بِنُورِ رَبِّهَا\nعلم من هذا أن الأنوار الموجودة تذهب يوم القيامة وتضمحل، وهو كذلك؛ فإن الله أخبر أن الشمس تكور، والقمر يُخسف، والنجوم تندثر، ويكون الناس في ظلمة؛ فتشرق عند ذلك الأرض بنور ربها، عندما يتجلّى وينزل للفصل بينهم. وذلك اليوم يجعل الله للخلق قوة، وينشئهم نشأة يَقوَونَ على أن لا يحرقهم نوره، ويتمكنون أيضًا من رؤيته، وإلا فنوره تعالى عظيم؛ لو كشفه لأحرقت سبحات وجهه ما انتهى إليه بصره من خلقه. السعدي:٧٣٠.\nما الدليل على أن الناس يحشرون أولًا في ظلمة؟ وما وجه الجمع بين الآية والأحاديث الدالة على أن نور الله يحرق ما انتهى إليه بصره من خلقه؟\nوَجِاْيٓءَ بِٱلنَّبِيِّۧنَ وَٱلشُّهَدَآءِ وَقُضِيَ بَيۡنَهُم بِٱلۡحَقِّ وَهُمۡ لَا يُظۡلَمُونَ ٦٩\nجيء بهم، فسألهم عمّا أجابتهم به أممهم،... والشهداء الذين استشهدوا في سبيل الله؛ فيشهدون يوم القيامة لمن ذب عن دين الله. القرطبي:١٨/٣١٥.\nلمَ جيء بالنبيين والشهداء في ذلك اليوم العصيب؟\nوَسِيقَ ٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ جَهَنَّمَ زُمَرًاۖ حَتَّىٰٓ إِذَا جَآءُوهَا فُتِحَتۡ أَبۡوَٰبُهَا\nوابتدئ في الخَبر بذكر مستحقي العقاب؛ لأنه الأهم في هذا المقام، إذ هو مقام إعادة الموعظة والترهيب للذين لم يتعظوا بما تكرر في القرآن من العظات مثل هذه، فأما أهل الثواب فقد حصل المقصود منهم، فما يذكر عنهم فإنما هو تكريرُ بشارة وثناء. ابن عاشور:٢٤/٦٩.\nما فائدة الابتداء بذكر مستحقي العذاب في الآية الكريمة؟\nوَسِيقَ ٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ جَهَنَّمَ زُمَرًاۖ حَتَّىٰٓ إِذَا جَآءُوهَا فُتِحَتۡ أَبۡوَٰبُهَا\nوإنَّما جُعلوا زمرًا لاختلاف دَرَجات كفرهم؛ فإن كان المراد بالذين كفروا مشركي قريش المقصودين بهذا الوعيد كان اختلافهم على حسب شدة تصلبهم في الكفر وما يخالطه من حَدَب على المسلمين أو فظاظة. ابن عاشور:٢٤/٦٩.\nلماذا جعل الكفار زُمرًا عند سوقهم إلى جهنم؟\nوَسِيقَ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ إِلَى ٱلۡجَنَّةِ زُمَرًاۖ\nوجَعلهم زُمرًا بحسب مراتب التقوى. ابن عاشور:٢٤/٧١.\nلماذا جُعل المتقون زمرًا في دخولهم الجنة؟\nوَسِيقَ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ إِلَى ٱلۡجَنَّةِ زُمَرًاۖ\nقال في حق الفريقين: (وسيق)؛ بلفظ واحد؛ فَسَوْقُ أهل النار: طردهم إليها بالخزي والهوان؛ كما يُفعل بالأسارى والخارجين على السلطان إذا سيقوا إلى حبس أو قتل، وَسَوْقُ أهل الجنان: سوق مراكبهم إلى دار الكرامة والرضوان؛ لأنه لا يُذهب بهم إلا راكبين؛ كما يفعل بمن يشرف ويكرم من الوافدين على بعض الملوك، فشتَّان ما بين السوقين! القرطبي:٤/١٤٢.\nهل ثمَّت فرق بين سوق أهل النار وسوق أهل الجنة؟\nحَتَّىٰٓ إِذَا جَآءُوهَا وَفُتِحَتۡ أَبۡوَٰبُهَا وَقَالَ لَهُمۡ خَزَنَتُهَا سَلَٰمٌ عَلَيۡكُمۡ طِبۡتُمۡ فَٱدۡخُلُوهَا خَٰلِدِينَ ٧٣\nلم يذكر الجواب هاهنا، وتقديره: ﴿حَتَّىٰٓ إِذَا جَآءُوهَا﴾، وكانت هذه الأمور من فتح الأبواب لهم إكرامًا وتعظيمًا، وتلقتهم الملائكة الخزنة بالبشارة والسلام والثناء، كما تلقى الزبانية الكفرة بالتثريب والتأنيب؛ فتقديره: إذا كان هذا سعدوا وطابوا وسُرُّوا وفرحوا بقدر كل ما يكون لهم فيه نعيم، وإذا حذف الجواب هاهنا ذهب الذهن كل مذهب في الرجاء والأمل. ابن كثير:٤/٦٨.\nما فائدة حذف جواب الشرط في هذه الآية؟"],[467,"§الزمر ، غافر\nwords\nحَآفِّينَمُحدِقِينَ، وَمُحِيطِينَ.\nوَقُضِيَ بَينَهُم بِالحَقّِ حُكِمَ بَينَ الخَلاَئِقِ بِالعَدلِ.\nذِي الطَّولِصَاحِبِ الإِنعَامِ وَالتَّفَضُّلِ.\nفَلاَ يَغرُركَفَلاَ يَخدَعكَ.\nلِيُدحِضُوالِيُبطِلُوا.\nوَقِهِمجَنِّبهُم.\ndeeds\nقل: \"اللهم أحسن عاقبتي في الأمور كلها، وأجرني من خزي الدنيا وعذاب الآخرة\".\nإذا قرأت فقل: يا غافر الذنب اغفر لي ذنبي، ويا قابل التوب اقبل توبتي\".\nاقرأ كتابًا تتعرف فيه على صفات الملائكة ووظائفهم.\nguid\nبيان عظمة الرب تعالى المتجلية في أسمائه: العزيز، العليم، غافر الذنب، قابل التوب، شديد العقاب، ذي الطول.\nاحذر من الاغترار بما أُعطي أعداء الإسلام من متاع الدنيا.\nلا تجادل بالباطل، وليكن همك الحق.\nrefl\nوَقِيلَ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ٧٥\nحذف فاعل القول لأنه غير معين، بل كل أحد يحمده على ذلك الحكم الذي حكم فيه؛ فيحمده أهل السماوات وأهل الأرض، والأبرار والفجار، والإنس والجن، حتى أهل النار... كأن الكون كله نطق بذلك. ابن القيم:٢/٤٠٣.\nلماذا ورد فعل (وقيل) في الآية الكريمة بصيغة المبني للمجهول؟\nوَقِيلَ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ٧٥\nأي: نطق الكون أجمعه -ناطقه وبهيمه- لله رب العالمين بالحمد في حكمه وعدله؛ ولهذا لم يسند القول إلى قائل، بل أطلقه، فدل على أن جميع المخلوقات شهدت له بالحمد. ابن كثير:٤/٧٠.\nلماذا عُبِّر بلفظ: (وقيل) ولم يُعبّر بلفظ: \"قالوا\" في الآية الكريمة؟\nتَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡعَلِيمِ ٢\nووصفُ الله بوصفي ﴿ٱلۡعَزِيزِ ٱلۡعَلِيمِ﴾ هنا تعريض بأن منكري تنزيل الكتاب منه مغلوبون مقهورون، وبأن الله يعلم ما تكنّه نفوسهم؛ فهو محاسبهم على ذلك، ورَمزٌ إلى أن القرآن كلام العزيز العليم؛ فلا يقدر غير الله على مثله، ولا يعلم غير الله أن يأتي بمثله. ابن عاشور:٢٤/٧٩.\nما مناسبة ختم الآية الكريمة بوصفي ﴿ٱلۡعَزِيزِ ٱلۡعَلِيمِ﴾؟\nغَافِرِ ٱلذَّنۢبِ وَقَابِلِ ٱلتَّوۡبِ شَدِيدِ ٱلۡعِقَابِ\nوهذه كقوله: ﴿نَبِّئۡ عِبَادِيٓ أَنِّيٓ أَنَا ٱلۡغَفُورُ ٱلرَّحِيمُ * وَأَنَّ عَذَابِي هُوَ ٱلۡعَذَابُ ٱلۡأَلِيمُ﴾ [الحجر: ٤٩-٥٠]، يقرن هذين الوصفين كثيرًا في مواضع متعددة ليبقى العبد بين الرجاء والخوف. ابن كثير:٤/٧١.\nلماذا قرن بين الغفران والعقاب في هذه الآية وغيرها من الآيات؟\nغَافِرِ ٱلذَّنۢبِ وَقَابِلِ ٱلتَّوۡبِ\nيجمَع للمذنب التائب بين رحمتين: بين أن يقبل توبته فيجعلها له طاعة، وبين أن يمحو عنه بها الذنوب التي تاب منها وندِم على فعلها؛ فيصبحَ كأنه لم يفعلها، وهذا فضل من الله. ابن عاشور:٢٤/٨٠.\nلماذا عطفت (قابل التوب) على ﴿غَافِرِ ٱلذَّنۢبِ﴾ في الآية الكريمة؟\nمَا يُجَٰدِلُ فِيٓ ءَايَٰتِ ٱللَّهِ إِلَّا ٱلَّذِينَ كَفَرُواْ فَلَا يَغۡرُرۡكَ تَقَلُّبُهُمۡ فِي ٱلۡبِلَٰدِ ٤\nوقوله: ﴿فَلَا يَغۡرُرۡكَ تَقَلُّبُهُمۡ فِي ٱلۡبِلَٰدِ﴾: يقول جل ثناؤه: فلا يخدعك يا محمد تصرفهم في البلاد، وبقاؤهم ومكثهم فيها، مع كفرهم بربهم؛ فتحسب أنهم إنَّما أُمهلوا وتقلبوا، فتصرفوا في البلاد مع كفرهم بالله، ولم يُعاجلوا بالنقمة والعذاب على كفرهم؛ لأنهم على شيء من الحق، فإنّا لم نمهلهم لذلك؛ ولكن ليبلغ الكتاب أجله، ولتحقَّ عليهم كلمة العذاب؛ عذاب ربك. الطبري:٢١/٣٥٢.\nما وجه إمهال الله تعالى للكفار مع إصرارهم على الكفر وتنعمهم بنعمه سبحانه؟\nٱلَّذِينَ يَحۡمِلُونَ ٱلۡعَرۡشَ وَمَنۡ حَوۡلَهُۥ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ وَيُؤۡمِنُونَ بِهِۦ\nإن قيل: ما فائدة قوله ﴿وَيُؤۡمِنُونَ بِهِۦ﴾، ومعلوم أن حملة العرش ومن حوله يؤمنون بالله؟ فالجواب: أن ذلك إظهار لفضيلة الإيمان وشرفه. ابن جزي:٢/٢٧٦.\nما الفائدة من قوله: ﴿وَيُؤۡمِنُونَ بِهِۦ﴾، علمًا بأن حملة العرش مؤمنون؟"],[468,"§غافر\nwords\nلَمَقتُ اللهِالمَقتُ: البُغضُ الشَّدِيدُ.\nيُنِيبُيَرجِعُ إِلَى طَاعَةِ اللهِ.\nيَومَ التَّلاَقِاليَومَ الَّذِي يَلتَقِي فِيهِ الأَوَّلُونَ وَالآخِرُونَ.\nبَارِزُونَظَاهِرُونَ أَمَامَ رَبِّهِم.\ndeeds\nمُر إخوانك وأهلك بالصلاة؛ رجاء أن يكونوا معك في الجنة.\nادعُ لغيرك من المؤمنين كما تدعو لنفسك اقتداء بالملائكة.\nحدد بعض ذنوبك وعيوبك، ثم سل الله التوبة قبل أن تعترف في الآخرة، ولا ينفعك ذلك.\nguid\nقال سعيد بن جبير: \"إن المؤمن إذا دخل الجنة سأل عن أبيه وابنه وأخيه، أين هم؟ فيقال: إنهم لم يبلغوا طبقتك في العمل. فيقول: إني إنَّما عملت لي ولهم، فيلحقون به في الدرجة\". ثم تلا سعيد بن جبير هذه الآية.\nاعلم أن أجلّ رحمةٍ ينالها العبد أن يقيه الله تعالى من تبعة السيئات.\nإذا عملت ما يرضي الله تعالى، وسخط عليك الكفار فلا عليك من سخطهم.\nrefl\nرَبَّنَا وَأَدۡخِلۡهُمۡ جَنَّٰتِ عَدۡنٍ ٱلَّتِي وَعَدتَّهُمۡ وَمَن صَلَحَ مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّيَّٰتِهِمۡۚ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ٨\nوتضمن ذلك أن المُقارن؛ من زوج وولد وصاحب، يسعد بقرينه، ويكون اتصاله به سببًا لخير يحصل له خارج عن عمله وسبب عمله، كما كانت الملائكة تدعو للمؤمنين ولمن صلح من آبائهم وأزواجهم وذرياتهم. السعدي:٧٣٣.\nفي هذه الآية حثٌّ على مصاحبة الصالحين؛ وضّح ذلك.\nرَبَّنَا وَأَدۡخِلۡهُمۡ جَنَّٰتِ عَدۡنٍ ٱلَّتِي وَعَدتَّهُمۡ وَمَن صَلَحَ مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّيَّٰتِهِمۡۚ\nأي: اجمع بينهم وبينهم؛ لتقر بذلك أعينهم بالاجتماع في منازل متجاورة. ابن كثير: ٤/٧٤.\nلماذا خص الآباء والأزواج والذريات بالذكر؟\nإِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ٨\n(العزيز): القاهر لكل شيء؛ فبعزتك تغفر ذنوبهم، وتكشف عنهم المحذور، وتوصلهم بها إلى كل خير. (الحكيم): الذي يضع الأشياء مواضعها؛ فلا نسألك يا ربنا أمرًا تقتضي حكمتك خلافه، بل من حكمتك التي أخبرت بها على ألسنة رسلك، واقتضاها فضلك: المغفرة للمؤمنين. السعدي:٧٣٢.\nما وجه ختم دعائهم بهاتين الصفتين: ﴿ٱلۡعَزِيزُ ٱلۡحَكِيمُ﴾؟\nإِنَّ ٱلَّذِينَ كَفَرُواْ يُنَادَوۡنَ لَمَقۡتُ ٱللَّهِ أَكۡبَرُ مِن مَّقۡتِكُمۡ أَنفُسَكُمۡ إِذۡ تُدۡعَوۡنَ إِلَى ٱلۡإِيمَٰنِ فَتَكۡفُرُونَ ١٠\nالمقت: البغض الذي يوجبه ذنب أو عيب، وهذه الحال تكون للكفار عند دخولهم النار؛ فإنهم إذا دخلوها مقتوا أنفسهم؛ أي: مقت بعضهم بعضًا، ويحتمل أن يمقت كل واحد منهم نفسه، فتناديهم الملائكة، وتقول لهم: مقت الله لكم في الدنيا على كفركم أكبر من مقتكم أنفسكم اليوم. ابن جزي:٢/٢٧٧.\nكيف يمقت الكفار أنفسهم في النار؟\nقَالُواْ رَبَّنَآ أَمَتَّنَا ٱثۡنَتَيۡنِ وَأَحۡيَيۡتَنَا ٱثۡنَتَيۡنِ فَٱعۡتَرَفۡنَا بِذُنُوبِنَا فَهَلۡ إِلَىٰ خُرُوجٖ مِّن سَبِيلٖ ١١\n﴿أَمَتَّنَا ٱثۡنَتَيۡنِ وَأَحۡيَيۡتَنَا ٱثۡنَتَيۡنِ﴾: إقرار بالبعث على أكمل الوجوه، طمعًا منهم أن يخرجوا عن المقت الذي مقتهم الله؛ إذ كانوا يُدعَون إلى الإسلام فيكفرون... فإن قيل: كيف يكون قولهم: ﴿أَمَتَّنَا ٱثۡنَتَيۡنِ وَأَحۡيَيۡتَنَا ٱثۡنَتَيۡنِ﴾ سببًا لاعترافهم بالذنوب؟ فالجواب: أنهم كانوا كافرين بالبعث، فلمّا رأوا الإماتة والإحياء قد تكرر عليهم، علموا أن الله قادر على البعث؛ فاعترفوا بذنوبهم؛ وهي إنكار البعث، وما أوجب لهم إنكاره من المعاصي؛ فإن من لم يؤمن بالآخرة لا يبالي بالوقوع في المعاصي. ابن جزي:٢/٢٧٨.\nفساد الاعتقاد سبب للوقوع في المعاصي، بين ذلك من الآية.\nيُلۡقِي ٱلرُّوحَ مِنۡ أَمۡرِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦ\n﴿يُلۡقِي ٱلرُّوحَ﴾: ينزل الوحي؛ سماه روحًا لأنه تحيا القلوب به. البغوي:٤/٣٨.\nلمَ سُمي الوحي روحًا؟\nيُلۡقِي ٱلرُّوحَ مِنۡ أَمۡرِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦ لِيُنذِرَ يَوۡمَ ٱلتَّلَاقِ ١٥\n﴿يَوۡمَ ٱلتَّلَاقِ﴾ يعني: يوم القيامة؛ وسمي بذلك لأن الخلائق يلتقون فيه، وقيل: لأنه يلتقي فيه أهل السموات والأرض، وقيل: لأنه يلتقي الخلق مع ربهم. ابن جزي:٢/٢٧٨.\nما يوم التلاق؟ ولم سمي بهذا الاسم؟"],[469,"§غافر\nwords\nيَومَ الآزِفَةِيَومَ القِيَامَةِ القَرِيبَ.\nلَدَى الحَنَاجِرِقُلُوبُهُم عِندَ حُلُوقِهِم مِن شِدَّةِ الكَربِ.\nكَاظِمِينَمُمتَلِئِينَ غَمًّا، وَحُزنًا.\nخَائِنَةَ الأَعيُنِمَا تَختَلِسُهُ العُيُونُ مِنَ النَّظَرِ إِلَى مَا لاَ يَحِلُّ.\nوَاقٍدَافِعٍ.\ndeeds\nتذكر أحدًا ظلمته، واطلب العفو منه، أو ادع له في ظهر الغيب، واستغفر من ذنبك.\nحافظ على طهارة قلبك اليوم، ولا تختلس النظر إلى ما لا يحل لك في الشارع أو السوق أو التلفاز أو الحاسب الآلي أو الهـاتف.\nتذكر دقائق قضيتها في غفلة أومعصية، وامكث مثلها في النظر إلى آيات القرآن؛ لعل الحسنات يذهبن السيئات.\nguid\nلا يُظلم أحد يوم القيامة بزيادة في سيئاته، أو نقص من حسناته.\nشدة هول يوم القيامة حتى إن القلوب تصل إلى الحناجر من شدة الفزع.\nاتخذ الناس النظر في آثار الأمم السابقة للتسلية، وإمضاء أوقات الفراغ، مبتعدين عن التفكر الذي أمر الله به في عقوبتهم.\nrefl\nإِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ ١٧\nلأنه العالم الذي لا يعزب عن علمه شيء، فلا يؤخر جزاء أحد للاشتغال بغيره، وكما يرزقهم في ساعة واحدة يحاسبهم كذلك في ساعة واحدة. القرطبي:١٨/٣٤١.\nبيّن عظمة الله تعالى في سرعة حسابه لعباده.\nوَأَنذِرۡهُمۡ يَوۡمَ ٱلۡأٓزِفَةِ إِذِ ٱلۡقُلُوبُ لَدَى ٱلۡحَنَاجِرِ\nسميت بذلك لأنها قريبة؛ إذ كل ما هو آت قريب... ﴿إِذِ ٱلۡقُلُوبُ لَدَى ٱلۡحَنَاجِرِ كَٰظِمِينَۚ﴾؛ وذلك أنها تزول عن أماكنها من الخوف حتى تصير إلى الحناجر، فلا هي تعود إلى أماكنها، ولا هي تخرج من أفواههم فيموتوا ويستريحوا. البغوي:٤/٣٩.\nلم سمي يوم القيامة بالآزفة؟ وكيف تكون القلوب لدى الحناجر؟\nيَعۡلَمُ خَآئِنَةَ ٱلۡأَعۡيُنِ وَمَا تُخۡفِي ٱلصُّدُورُ ١٩\nيخبر -عز وجل- عن علمه التام المحيط بجميع الأشياء: جليلها وحقيرها، صغيرها وكبيرها، دقيقها ولطيفها؛ ليحذر الناس علمه فيهم، فيستحيوا من الله تعالى حق الحياء، ويتقوه حق تقواه، ويراقبوه مراقبة من يعلم أنه يراه. ابن كثير:٤/٧٧.\nما الفائدة العملية التي يخرج بها المسلم من هذه الآية؟\nيَعۡلَمُ خَآئِنَةَ ٱلۡأَعۡيُنِ وَمَا تُخۡفِي ٱلصُّدُورُ ١٩\nقال ابن عباس -رضي الله عنهما-: \"هو الرجل يكون جالسًا مع القوم، فتمر المرأة فيسارقهم النظر إليها\". وعنه: \"هو الرجل ينظر إلى المرأة، فإذا نظر إليه أصحابه غض بصره، فإذا رأى منهم غفلة تدسس بالنظر، فإذا نظر إليه أصحابه غض بصره، وقد علم الله -عز وجل- منه أنه يود لو نظر إلى عورتها\"... قال ابن عباس: \"﴿وَمَا تُخۡفِي ٱلصُّدُورُ﴾ أي: هل يزني بها لو خلا بها، أو لا؟\". القرطبي:١٨/٣٤٣.\nكيف تكون خائنة الأعين؟ وما الذي تخفيه الصدور؟\nوَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلۡطَٰنٖ مُّبِينٍ ٢٣\nقص الله تعالى على رسوله قصة موسى مع فرعون؛ ليسلِّيه بها ويصبّره، وليعلمه أن البلاء مهما اشتد يعقبه الفرج، وأن الله ناصره على قومه كما نصر موسى على فرعون وقومه. الجزائري:٤/٥٢٧.\nما مناسبة ذكر قصة موسى مع فرعون لما قبلها من الآيات؟\nإِلَىٰ فِرۡعَوۡنَ وَهَٰمَٰنَ وَقَٰرُونَ فَقَالُواْ سَٰحِرٞ كَذَّابٞ ٢٤ فَلَمَّا جَآءَهُم بِٱلۡحَقِّ مِنۡ عِندِنَا قَالُواْ ٱقۡتُلُوٓاْ أَبۡنَآءَ ٱلَّذِينَ ءَامَنُواْ مَعَهُۥ وَٱسۡتَحۡيُواْ نِسَآءَهُمۡۚ وَمَا كَيۡدُ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٖ ٢٥\nقال هؤلاء الثلاثة وأجمع رأيهم على أن يُقتل أبناء بني إسرائيل أتباع موسى وشبانهم وأهل القوة منهم، وأن يُسْتَحيَى النساء للخدمة والاسترقاق...، وقوله تعالى: ﴿وَمَا كَيۡدُ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٍ﴾ عبارة وجيزة تعطي قوتها أن هؤلاء الثلاثة لم يُقْدِرهم الله تعالى على قتل أحد من بني إسرائيل، ولا نجحت لهم فيه سعاية، بل أضل الله سعيهم وكيدهم. ابن عطية:٤/٥٥٤.\nإرادة الله فوق إرادة الملوك؛ وضّح ذلك من خلال الآيتين.\nفَلَمَّا جَآءَهُم بِٱلۡحَقِّ مِنۡ عِندِنَا قَالُواْ ٱقۡتُلُوٓاْ أَبۡنَآءَ ٱلَّذِينَ ءَامَنُواْ مَعَهُۥ وَٱسۡتَحۡيُواْ نِسَآءَهُمۡۚ وَمَا كَيۡدُ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٖ ٢٥\nتدبر هذه النكتة التي يكثر مرورها بكتاب الله تعالى: إذا كان السياق في قصة معينة أو على شيء معين، وأراد الله أن يحكم على ذلك المعين بحكم لا يختص به، ذكر الحكم وعلقه على الوصف العام؛ ليكون أعم، وتندرج فيه الصورة التي سيق الكلام لأجلها، وليندفع الإيهام باختصاص الحكم بذلك المعين؛ فلهذا لم يقل: \"وما كيدهم إلا في ضلال\"، بل قال: ﴿وَمَا كَيۡدُ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٍ﴾. السعدي:٧٣٦.\nلماذا ختمت الآية بلفظ عام: ﴿وَمَا كَيۡدُ ٱلۡكَٰفِرِينَ﴾، ولم تختم بلفظ: \"وما كيد فرعون\" أو \"وما كيدهم\"؟"],[470,"§غافر\nwords\nعُذتُاستَجَرتُ.\nظَاهِرِينَغَالِبِينَ عَالِينَ.\nيَومَ التَّنَادِيَومَ القِيَامَةِ الَّذِي يُنَادِي النَّاسُ فِيهِ بَعضُهُم بَعضًا.\nمُدبِرِينَهَارِبِينَ.\nعَاصِمٍمَانِعٍ يَمنَعُكُم.\ndeeds\nإذا خفت من مجرم فقل: \"اللهم إنا نعوذ بك من شرورهم، وندرأ بك في نحورهم\".\nدافع عن أحد العلماء أو الدعاة ممن يستهزئ بهم السفهاء برسالة أو كلمة مقتديًا بمؤمن آل فرعون.\nاستعذ بالله من الإسراف والكذب والكبر.\nguid\nسيرة المتكلم تدل على صدقه أو كذبه.\nالله سبحانه هو ملاذ المؤمن من كل خوف.\nمِن أبعد الناس عن الهداية مَن أسرف في المعاصي ثم كذب وزعم أن الله أمر بها.\nrefl\nوَقَالَ فِرۡعَوۡنُ ذَرُونِيٓ أَقۡتُلۡ مُوسَىٰ وَلۡيَدۡعُ رَبَّهُۥٓۖ إِنِّيٓ أَخَافُ أَن يُبَدِّلَ دِينَكُمۡ أَوۡ أَن يُظۡهِرَ فِي ٱلۡأَرۡضِ ٱلۡفَسَادَ ٢٦\nوقد حمله غروره وقلة تدبره في الأمور على ظن أن ما خالف دينهم يعدّ فسادًا؛ إذ ليست لهم حجة لدينهم غير الإِلف والانتفاع العاجل. ابن عاشور:٢٤/١٢٥.\nعادات الآباء والأجداد إذا كانت فاسدة فهي مانعة من الهداية؛ وضّح ذلك.\nوَقَالَ مُوسَىٰٓ إِنِّي عُذۡتُ بِرَبِّي وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرٖ لَّا يُؤۡمِنُ بِيَوۡمِ ٱلۡحِسَابِ ٢٧\nمن لم يؤمن بيوم الحساب مصدقًا، لم يكن للثواب على الإحسان راجيًا، ولا للعقاب على الإساءة وقبيح ما يأتي من الأفعال خائفًا. الطبري:٢١/٣٧٥.\nلماذا خص موسى -عليه السلام- الاستعاذة بالله ممن لا يؤمن بيوم الحساب؟\nوَقَالَ رَجُلٞ مُّؤۡمِنٞ مِّنۡ ءَالِ فِرۡعَوۡنَ يَكۡتُمُ إِيمَٰنَهُۥٓ أَتَقۡتُلُونَ رَجُلًا أَن يَقُولَ رَبِّيَ ٱللَّهُ وَقَدۡ جَآءَكُم بِٱلۡبَيِّنَٰتِ مِن رَّبِّكُمۡۖ\nقد أثنى الله على رجل مؤمن من آل فرعون كتم إيمانه وأسرَّه، فجعله الله تعالى في كتابه، وأثبت ذكره في المصاحف لكلام قاله في مجلس من مجالس الكفر؛ وأين هو من عمر بن الخطاب -رضي الله عنه-: جرَّد سيفه بمكة، وقال: \"والله لا أعبد الله سرًّا بعد اليوم\". ابن عطية:٤/٥٥٥.\nهذه الآية تدل على فضائل الصحابة؛ وضحها.\nوَإِن يَكُ كَٰذِبٗا فَعَلَيۡهِ كَذِبُهُۥۖ وَإِن يَكُ صَادِقٗا يُصِبۡكُم بَعۡضُ ٱلَّذِي يَعِدُكُمۡ\nولم يكن ذلك لشكٍ منه في رسالته وصدقه، ولكن تلطفًا في الاستكفاف، واستنزالًا عن الأذى. القرطبي:١٨/٣٤٨-٣٤٩.\nهل قول مؤمن آل فرعون لشك منه في صدق موسى -عليه السلام-؟ وأي أدب دعوي نتعلمه من ذلك الأسلوب؟\nوَإِن يَكُ صَادِقٗا يُصِبۡكُم بَعۡضُ ٱلَّذِي يَعِدُكُمۡ\nوإنَّما قال بعض ولم يقل كل مع أن الذي يصيبهم هو كل ما يعدهم؛ ليلاطفهم في الكلام، ويبعد عن التعصب لموسى، ويظهر النصيحة لفرعون وقومه؛ فيرتجى إجابتهم للحق. ابن جزي:٢/٢٨٠.\nلمَ قال مؤمن آل فرعون: ﴿بَعۡضُ ٱلَّذِي يَعِدُكُمۡۖ﴾ مع أن ما سيصيبهم هو كل ما وعدهم به؟\nوَقَالَ ٱلَّذِيٓ ءَامَنَ يَٰقَوۡمِ إِنِّيٓ أَخَافُ عَلَيۡكُم مِّثۡلَ يَوۡمِ ٱلۡأَحۡزَابِ ٣٠\n﴿وَقَالَ ٱلَّذِيٓ ءَامَنَ﴾ مكررًا دعوة قومه، غير آيس من هدايتهم، كما هي حالة الدعاة إلى الله تعالى؛ لا يزالون يدعون إلى ربهم، ولا يردهم عن ذلك رادٌّ، ولا يثنيهم عتو من دعوه عن تكرار الدعوة. السعدي:٧٣٧.\nفي الآية توجيه رفيع لأصحاب الدعوة إلى الله بعدم اليأس؛ بيِّنه.\nوَيَٰقَوۡمِ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ يَوۡمَ ٱلتَّنَادِ ٣٢\nيوم القيامة يُدعى كل أناس بإمامهم، وينادي بعضهم بعضًا؛ فينادي أصحاب الجنة أصحاب النار، وأصحاب النار أصحاب الجنة، وينادَى أصحاب الأعراف، وينادَى بالسعادة والشقاوة: ألا إن فلان ابن فلان قد سعد سعادةً لا يشقى بعدها أبدًا، وفلان ابن فلان قد شقى شقاوة لا يسعد بعدها أبدًا، وينادَى حين يذبح الموت: يا أهل الجنة خلود فلا موت، ويا أهل النار خلود فلا موت. البغوي:٤/٤٢.\nلماذا سمي يوم القيامة بيوم التناد؟"],[471,"§غافر\nwords\nشَكٍّرِيبَةٍ.\nمُرتَابٌشَاكٌّ فِي اللهِ.\nيَطبَعُيَختِمُ.\nصَرحًابِنَاءً عَظِيمًا.\nتَبَابٍخَسَارٍ، وَبَوَارٍ.\ndeeds\nاستعذ بالله من الجدال بغير علم ومن مقت الله.\nادع إلى الله تعالى أحد الغافلين بحكمة وأسلوب حسن أسوة بصالحي الأمم السابقة.\nاعمل اليومَ عملًا لم تكن قد عملته من قبل، راجيًا من الله -سبحانه وتعالى- أن يدخلك به الجنة.\nguid\nاحذر من الجدال بغير علم.\nبداية الهلاك أن تزين لك أعمالك السيئة فتراها حسنة -والعياذ بالله-.\nكن واثقًا بالله تعالى في نصره وتمكينه لأوليائه، وخذلانه لأعدائه.\nrefl\nوَلَقَدۡ جَآءَكُمۡ يُوسُفُ مِن قَبۡلُ بِٱلۡبَيِّنَٰتِ فَمَا زِلۡتُمۡ فِي شَكّٖ مِّمَّا جَآءَكُم بِهِۦۖ حَتَّىٰٓ إِذَا هَلَكَ قُلۡتُمۡ لَن يَبۡعَثَ ٱللَّهُ مِنۢ بَعۡدِهِۦ رَسُولٗاۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَنۡ هُوَ مُسۡرِفٞ مُّرۡتَابٌ ٣٤\nتوسم فيهم قلة جدوى النصح لهم، وأنهم مصممون على تكذيب موسى، فارتقى في موعظتهم إلى اللوم على ما مضى، ولتذكيرهم بأنهم من ذرية قوم كذّبوا يوسف لما جاءهم بالبينات، فتكذيب المرشدين إلى الحق... معروفة في أسلافهم، فتكون سجية فيهم. ابن عاشور:٢٤/١٣٨.\nما مناسبة الآية الكريمة لما قبلها؟\nكَبُرَ مَقۡتًا عِندَ ٱللَّهِ وَعِندَ ٱلَّذِينَ ءَامَنُواْۚ\nوكذلك عباده المؤمنون يمقتون على ذلك أشد المقت موافقة لربهم، وهؤلاء خواص خلق الله تعالى؛ فمقتهم دليل على شناعة من مقتوه. السعدي:٧٣٨.\nمن يمقته العلماء والصالحون من الناس هو في وضع خطير، وعليه أن يتدارك نفسه، بيِّن وجه ذلك من خلال الآية.\nأَسۡبَٰبَ ٱلسَّمَٰوَٰتِ فَأَطَّلِعَ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّي لَأَظُنُّهُۥ كَٰذِبٗاۚ\nولما قال فرعون بمحضر من مَلَأِهِ: ﴿فَأَطَّلِعَ إِلَىٰٓ إِلَٰهِ مُوسَىٰ﴾ اقتضى كلامه الإقرار ب﴿لَهُۥ مُوسَىٰ﴾؛ فاستدرك ذلك استدراكًا قلقًا بقوله: ﴿وَإِنِّي لَأَظُنُّهُۥ كَٰذِبًاۚ﴾. ابن عطية:٤/٥٦٠.\nما المناسبة بين أول الآية وقول فرعون: ﴿وَإِنِّي لَأَظُنُّهُۥ كَٰذِبًاۚ﴾؟\nأَسۡبَٰبَ ٱلسَّمَٰوَٰتِ فَأَطَّلِعَ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّي لَأَظُنُّهُۥ كَٰذِبٗاۚ وَكَذَٰلِكَ زُيِّنَ لِفِرۡعَوۡنَ سُوٓءُ عَمَلِهِۦ وَصُدَّ عَنِ ٱلسَّبِيلِۚ وَمَا كَيۡدُ فِرۡعَوۡنَ إِلَّا فِي تَبَابٖ ٣٧\nوجملة ﴿وَإِنِّي لَأَظُنُّهُۥ كَٰذِبًاۚ﴾ معترضة للاحتراس من أن يظن هامان وقومه أن دعوة موسى أوهنت منه يقينَه بدينه وآلهته، وأنه يروم أن يبحث بحث متأمل ناظر في أدلة المعرفة، فحقق لهم أنه ما أراد بذلك إلا نفي ما ادعاه موسى بدليل الحس. ابن عاشور:٢٤/١٤٧.\nما فائدة احتراس فرعون بجملة: ﴿وَإِنِّي لَأَظُنُّهُۥ كَٰذِبًاۚ﴾؟\nوَمَا كَيۡدُ فِرۡعَوۡنَ إِلَّا فِي تَبَابٖ ٣٧\nوسمي كيدًا لأنه عملٌ ليس المراد به ظاهره، بل أريد به الإِفضاء إلى إيهام قومه كذب موسى -عليه السلام-. ابن عاشور:٢٤/١٤٨.\nلماذا سمي ما أمر به فرعون من بناء الصرح كيدًا؟\nوَمَا كَيۡدُ فِرۡعَوۡنَ إِلَّا فِي تَبَابٖ ٣٧\nوما احتيال فرعون الذي يحتال للاطلاع إلى إله موسى، إلا في خسار وذهاب مال وغبن؛ لأنه ذهبت نفقته التي أنفقها على الصرح باطلًا، ولم ينل بما أنفق شيئًا مما أراده؛ فذلك هو الخسار والتباب. الطبري:٢١/٣٨٨.\nما التَّباب؟ ولماذا وُصِف كيد فرعون بأنه في تباب؟\nيَٰقَوۡمِ إِنَّمَا هَٰذِهِ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا مَتَٰعٞ وَإِنَّ ٱلۡأٓخِرَةَ هِيَ دَارُ ٱلۡقَرَارِ ٣٩\nأي: يتمتع بها قليلًا، ثم تنقطع وتزول. ﴿وَإِنَّ ٱلۡأٓخِرَةَ هِيَ دَارُ ٱلۡقَرَارِ﴾ أي: الاستقرار والخلود، ومراده بالدار الآخرة: الجنة والنار؛ لأنهما لا يفنيان. القرطبي:١٨/٣٦١.\nبيّن كيف دعاهم إلى الله تعالى ببيان حقيقة الدنيا والآخرة."],[472,"§غافر\nwords\nلاَ جَرَمَحَقًّا.\nلَيسَ لَهُ دَعوَةٌلاَ يَستَحِقُّ الدَّعوَةَ إِلَى عِبَادَتِهِ، وَلاَ يُلجَأُ إِلَيهِ؛ لِعَجزِهِ.\nوَأُفَوِّضُأَعتَصِمُ، وَأَلجَأُ، وَأَتَوَكَّلُ.\nوَحَاقَنَزَلَ، وَأَحَاطَ.\nيَتَحَآجُّونَيَتَخَاصَمُونَ.\nمُغنُونَدَافِعُونَ.\ndeeds\nادع مذنبًا إلى التوبة، أو كافرًا إلى الإسلام، وأظهر شفقتك وحرصك عليه.\nتذكر أمرًا أهمّك، وتوكل فيه على الله تعالى؛ فهو حسبك.\nزرِ المقبرة، ثم استعذ بالله من عذاب القبر.\nguid\nاستخدم الأسلوب الوعظي المؤثر في دعوتك إلى الله.\nنِعم ما ختم به مؤمن آل فرعون وعظَهُ ونصحه لقومه.\nالغبن الشديد لضعاف العقول؛ يقادون في الدنيا ويتبرأ منهم في الآخرة.\nrefl\nوَأُفَوِّضُ أَمۡرِيٓ إِلَى ٱللَّهِۚ إِنَّ ٱللَّهَ بَصِيرُۢ بِٱلۡعِبَادِ ٤٤ فَوَقَىٰهُ ٱللَّهُ سَيِّـَٔاتِ مَا مَكَرُواْۖ\nدليل على أن من فوَّض أمره إلى الله -عز وجل- كان الله معه. ابن جزي:٢/٢٨٢.\nما الذي يستفيده المسلم من هاتين الآيتين؟\nفَوَقَىٰهُ ٱللَّهُ سَيِّـَٔاتِ مَا مَكَرُواْۖ\nأي: من إلحاق أنواع العذاب به؛ فطلبوه، فما وجدوه؛ لأنه فوَّض أمره إلى الله. القرطبي:١٨/٣٦٣.\nما الذي آل إليه أمر مؤمن آل فرعون لمَّا فوض أمره لله تعالى؟\nوَحَاقَ بِـَٔالِ فِرۡعَوۡنَ سُوٓءُ ٱلۡعَذَابِ ٤٥\nوإنَّما كان الغَرَق سوء عذاب؛ لأن الغريق يعذب باحتباس النفَس مدة، وهو يطفو على الماء ويغوص فيه، ويُرعبه هول الأمواج وهو مُوقن بالهلاك، ثم يكون عُرضة لأكل الحيتان حيًّا وميِّتًا، وذلك ألمٌ في الحياة، وخزيٌ بعد الممات، يُذكرون به بين الناس. ابن عاشور:٢٤/١٥٨.\nلماذا يعد التعبير عن الغرق سوء العذاب؟\nٱلنَّارُ يُعۡرَضُونَ عَلَيۡهَا غُدُوّٗا وَعَشِيّٗاۚ وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ أَدۡخِلُوٓاْ ءَالَ فِرۡعَوۡنَ أَشَدَّ ٱلۡعَذَابِ ٤٦\nأرواحهم تعرض على النار صباحًا ومساءً إلى قيام الساعة، فإذا كان يوم القيامة اجتمعت أرواحهم وأجسادهم في النار، ولهذا قال: ﴿وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ أَدۡخِلُوٓاْ ءَالَ فِرۡعَوۡنَ أَشَدَّ ٱلۡعَذَابِ﴾ أي: أشده ألمًا، وأعظمه نكالًا، وهذه الآية أصل كبير في استدلال أهل السنة على عذاب البرزخ في القبور؛ وهي قوله تعالى: ﴿ٱلنَّارُ يُعۡرَضُونَ عَلَيۡهَا غُدُوًّا وَعَشِيًّاۚ﴾. ابن كثير:٤/٨٣.\nكيف تستدل بهذه الآية على وجود عذاب القبر؟\nوَإِذۡ يَتَحَآجُّونَ فِي ٱلنَّارِ فَيَقُولُ ٱلضُّعَفَٰٓؤُاْ لِلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا كُنَّا لَكُمۡ تَبَعٗا فَهَلۡ أَنتُم مُّغۡنُونَ عَنَّا نَصِيبٗا مِّنَ ٱلنَّارِ ٤٧\nوقول الضعفاء للكبراء هذا الكلامَ يحتمل أنه على حقيقته، فهو ناشيء عما اعتادوه من اللَّجَأِ إليهم في مهمهم حين كانوا في الدنيا، فخالوا أنهم يتولون تدبير أمورهم في ذلك المكان؛ ولهذا أجاب الذين استكبروا بما يفيد أنهم اليوم سواء في العجز وعدم الحيلة، فقالوا: ﴿إِنَّا كُلٌّ فِيهَآ﴾ أي: لو أغنينا عنكم لأغنينا عن أنفسنا. ويحتمل أن قول الضعفاء ليس مستعملًا في حقيقة الحث على التخفيف عنهم، ولكنه مستعمل في التوبيخ، أي: كنتم تدعوننا إلى دين الشرك؛ فكانت عاقبة ذلك أنا صرنا في هذا العذاب، فهل تستطيعون الدفع عنا؟ ابن عاشور:٢٤/١٦١.\nوضح فائدة قول الضعفاء للكبراء هذا القول الوارد في الآية الكريمة؟\nقَالَ ٱلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا كُلّٞ فِيهَآ إِنَّ ٱللَّهَ قَدۡ حَكَمَ بَيۡنَ ٱلۡعِبَادِ ٤٨\nوفي هذه الآية عبرة لزعماء الأمم وقادتهم... فإن كان إقدامهم ومغامرتهم بأنفسهم وأممِهم على علم بعواقب ذلك؛ كانوا أحرياء بالمذمة والخزي في الدنيا، ومضاعفة العذاب في الآخرة...كما قال تعالى: ﴿وَلَيَحۡمِلُنَّ أَثۡقَالَهُمۡ وَأَثۡقَالٗا مَّعَ أَثۡقَالِهِمۡ﴾ [العنكبوت: ١٣]، وإن كان قَحمهم أنفسهم في مضائق الزعامة عن جهل بعواقب قصورهم وتقصيرهم؛ فإنهم ملومون على عدم التوثق من كفاءتهم لتدبير الأمة، فيخبطوا بها خبط عشواء؛ حتى يزلوا بها، فيَهوُوا بها من شواهق بعيدة. ابن عاشور:٢٤/١٦٣.\nاذكر عبرةً مستفادة للقادة والزعماء من الآية الكريمة.\nوَقَالَ ٱلَّذِينَ فِي ٱلنَّارِ لِخَزَنَةِ جَهَنَّمَ ٱدۡعُواْ رَبَّكُمۡ يُخَفِّفۡ عَنَّا يَوۡمٗا مِّنَ ٱلۡعَذَابِ ٤٩\nوفي إضافة (ربّ) إلى ضمير المخاطبين ضرب من الإِغراء بالدعاء؛ أي: لأنكم أقرب إلى استجابته لكم، ولمَّا ظنُّوهم أرجى للاستجابة؛ سألوا التخفيف يومًا من أزمنة العذاب، وهو أنفع لهم من تخفيف قوة النار الذي سألوه من مستكبريهم. ابن عاشور:٢٤/١٦٤.\nما فائدة إضافة كلمة (رب) إلى ضمير المخاطب: (ربكم)؟"],[473,"§غافر\nwords\nالأَشهَادُمَن يَشهَدُونَ عَلَى المُكَذِّبِينَ؛ مِنَ المَلاَئِكَةِ وَالأَنبِيَاءِ وَالمُؤمِنِينَ.\nمَعذِرَتُهُمعُذرُهُم.\nلأِولِي الأَلبَابِلأِصحَابِ العُقُولِ السَّلِيمَةِ.\nبِالعَشِيِّ وَالإِبكَارِفِي آخِرِ النَّهَارِ، وَأَوَّلِهِ.\nسُلطَانٍحُجَّةٍ بَيِّنَةٍ.\nمَا هُم بِبَالِغِيهِلَيسُوا بِوَاصِلِينَ لِلعُلُوِّ عَلَيكَ، وَلاَ لِلفَضلِ الَّذِي خَصَّكَ اللهُ بِهِ.\ndeeds\nتذكر ذنوبًا فعلتها، ثم أكثر الاستغفار منها.\nقل: \"سبحان الله وبحمده\" مائة مرة في المساء وفي الصباح.\nاستعذ بالله من الكبر، فإنه يمنع من قبول الحق.\nguid\nاصبر وصابر في طريق الحق؛ يحدوك لذلك يقينك بأن وعد الله حق.\nأكثر من يجادل بالباطل ليزيل به الحق إنَّما يجادل عن كِبر.\nمن قدر على خلق الشيء العظيم فهو أقدر على إحياء الضعيف.\nrefl\nقَالُوٓاْ أَوَ لَمۡ تَكُ تَأۡتِيكُمۡ رُسُلُكُم بِٱلۡبَيِّنَٰتِۖ قَالُواْ بَلَىٰۚ قَالُواْ فَٱدۡعُواْۗ وَمَا دُعَٰٓؤُاْ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٍ ٥٠\nأي: كما توليتم الإعراض عن الرسل استبدادًا بآرائكم فتولَّوا اليومَ أمرَ أنفسكم؛ فادعوا أنتم. ابن عاشور:٢٤/١٦٦.\nما مناسبة أمر المشركين بالدعاء لأنفسهم لما قبله؟\nوَمَا دُعَٰٓؤُاْ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٍ ٥٠\nالكفر محبط لجميع الأعمال، صادّ لإجابة الدعاء. السعدي:٧٣٩.\nاذكر بعض المساوئ التي تعود على أهل الكفر من جراء كفرهم.\nإِنَّا لَنَنصُرُ رُسُلَنَا وَٱلَّذِينَ ءَامَنُواْ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَيَوۡمَ يَقُومُ ٱلۡأَشۡهَٰدُ ٥١\nقال ابن عباس -رضي الله عنهما-: بالغلبة والقهر، وقال الضحاك: بالحجة، وفي الآخرة بالعذر، وقيل: بالانتقام من الأعداء في الدنيا والآخرة. وكل ذلك قد كان للأنبياء والمؤمنين؛ فهم منصورون بالحجة على من خالفهم، وقد نصرهم الله بالقهر على من ناوأهم وإهلاك أعدائهم، ونصرهم بعد أن قُتلوا بالانتقام من أعدائهم؛ كما نصر يحيى بن زكريا لمَّا قُتِل؛ قُتِل به سبعون ألفًا، فهم منصورون بأحد هذه الوجوه. البغوي:٤/٤٧.\nهل النصر خاص بالرسل؟ وهل الانتصار متوقف على هلاك أعدائهم؟\nوَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡهُدَىٰ وَأَوۡرَثۡنَا بَنِيٓ إِسۡرَٰٓءِيلَ ٱلۡكِتَٰبَ ٥٣\nهذا من أوضح مُثُل نصر الله رسله والذين آمنوا بهم، وهو أشبه الأمثال بالنصر الذي قدره الله تعالى للنبي -صلى الله عليه وسلم- والمؤمنين؛ فإن نصر موسى على قوم فرعون كوَّن الله به أمةً عظيمة لم تكن يؤبه بها، وأوتيت شريعة عظيمة، ومُلكًا عظيمًا. وكذلك كان نصر النبي -صلى الله عليه وسلم- والمؤمنين، وكان أعظمَ من ذلك وأكملَ وأشرفَ. ابن عاشور:٢٤/١٦٩.\nكيف كانت قصة موسى -عليه السلام- من أوضح الأمثلة على نصر الله تعالى للمؤمنين؟\nإِنَّ ٱلَّذِينَ يُجَٰدِلُونَ فِيٓ ءَايَٰتِ ٱللَّهِ بِغَيۡرِ سُلۡطَٰنٍ أَتَىٰهُمۡ إِن فِي صُدُورِهِمۡ إِلَّا كِبۡرٞ مَّا هُم بِبَٰلِغِيهِۚ\nأي: تكبُر وتعاظُم يمنعهم من أن يتبعوك وأن ينقادوا إليك. ابن جزي:٢/٢٨٣.\nما السبب الذي منع الكفار من اتباع النبي -صلى الله عليه وسلم-؟\nإِنَّ ٱلَّذِينَ يُجَٰدِلُونَ فِيٓ ءَايَٰتِ ٱللَّهِ بِغَيۡرِ سُلۡطَٰنٍ أَتَىٰهُمۡ إِن فِي صُدُورِهِمۡ إِلَّا كِبۡرٞ مَّا هُم بِبَٰلِغِيهِۚ\nوفائدة هذا القيد: تشنيع مجادلتهم؛ وإلا فإن المجادلة في آيات الله لا تكون إلا بغير سلطان؛ لأن آيات الله لا تكون مخالفة للواقع، فهذا القيد نظير القيد في قوله: ﴿وَمَنۡ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَيۡرِ هُدٗى مِّنَ ٱللَّهِ﴾ [القصص: ٥٠]. ابن عاشور:٢٤/١٧٣.\nما فائدة تقييد المجادلة في آيات الله بأنها بغير سلطان؟\nوَمَا يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَلَا ٱلۡمُسِيٓءُۚ قَلِيلٗا مَّا تَتَذَكَّرُونَ ٥٨\nوإنَّما قدم ذكر الأعمى على ذكر البصير -مع أن البصر أشرف من العمى بالنسبة لذات واحدة، والمشبهَ بالبصير أشرفُ من المشبه بالأعمى؛ إذ المشبه بالبصير المؤمنون-؛ فقدم ذكر تشبيه الكافرين مراعاةً لكون الأهمّ في المقام بيانَ حال الذين يجادلون في الآيات؛ إذ هم المقصود بالموعظة. ابن عاشور:٢٤/١٧٨.\nلماذا قدم ذكر الأعمى على البصير مع أن الأشرف هو البصير؟"],[474,"§غافر\nwords\nلاَ رَيبَ فِيهَالاَ شَكَّ فِيهَا.\nدَاخِرِينَصَاغِرِينَ، حَقِيرِينَ.\nلِتَسكُنُوالِتَرتَاحُوا.\nمُبصِرًامُضِيئًا.\nفَأَنَّى تُؤفَكُونَكَيفَ تُصرَفُونَ عَنِ الإِيمَانِ بِهِ؟!\nيُؤفَكُيُصرَفُ.\ndeeds\nأكثر اليوم من الدعاء حتى لا تكون من المستكبرين عن عبادة الله.\nاعمل اليوم عملًا تظهر فيه الذل لربك.\nنم هذه الليلة مبكرًا، واستيقظ مبكرًا؛ حتى تكون موافقًا للطبيعة والفطرة التي خلقك الله عليها.\nguid\nبيان إنعام الله وإفضاله، والمطالبة بشكر الله تعالى.\nالساعة قريبة؛ ماذا أعددت لها؟\nأخلص لله تعالى في جميع عملك.\nrefl\nوَقَالَ رَبُّكُمُ ٱدۡعُونِيٓ أَسۡتَجِبۡ لَكُمۡۚ إِنَّ ٱلَّذِينَ يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِي سَيَدۡخُلُونَ جَهَنَّمَ دَاخِرِينَ ٦٠\n﴿يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِي﴾ بمعنى: يستكبرون عن الرغبة إليّ؛ كما قال -صلى الله عليه وسلم-: «من لم يسأل الله يغضب عليه». وأمَّا قوله -صلى الله عليه وسلم-: «الدعاء هو العبادة»؛ فمعناه أن الدعاء والرغبة إلى الله هي العبادة؛ لأن الدعاء يظهر فيه افتقار العبد وتضرعه إلى الله. ابن جزي:٢/٢٨٤.\nكيف نستدل بهذه الآية على أن الدعاء هو العبادة؟\nوَقَالَ رَبُّكُمُ ٱدۡعُونِيٓ أَسۡتَجِبۡ لَكُمۡۚ إِنَّ ٱلَّذِينَ يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِي سَيَدۡخُلُونَ جَهَنَّمَ دَاخِرِينَ ٦٠\nكان سفيان الثوري يقول: \"يا من أَحَبُ عباده إليه من سأله فأكثر سؤاله، ويا من أَبْغَضُ عباده إليه من لم يسأله؛ وليس أحد كذلك غيرك يا رب\"، وفي هذا المعنى يقول الشاعر: الله يغضبُ إن تركت سؤاله * وبُنَيّ آدم حين يُسأَلُ يَغضَبُ. ابن كثير:٤/٨٧.\nقارن بين سؤالك اللهَ وسؤالك الناسَ.\nإِنَّ ٱلَّذِينَ يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِي سَيَدۡخُلُونَ جَهَنَّمَ دَاخِرِينَ ٦٠\nأي: ذليلين حقيرين؛ يجتمع عليهم العذاب والإهانة؛ جزاء على استكبارهم.السعدي:٧٤١.\nتحدث عن قاعدة \"الجزاء من جنس العمل\" في ضوء هذه الآية.\nٱللَّهُ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ قَرَارٗا وَٱلسَّمَآءَ بِنَآءٗ\nولمّا كان المقصود الأول من هذه الآية الامتنان -كما دل عليه قوله: (لكم)- قُدمت الأرض على السماء؛ لأن الانتفاع بها محسوس، وذكرت السماء بعدها كما يستحضر الشيء بضده. ابن عاشور:٢٤/١٨٩.\nلماذا قدمت الأرض على السماء في الآية الكريمة؟\nوَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡ\nقال مقاتل: \"خلقكم فأحسن خلقكم\"، قال ابن عباس: \"خلق ابن آدم قائمًا معتدلًا يأكل ويتناول بيده، وغير ابن آدم يتناول بفيه\". البغوي:٤/٥٢.\nبيّن ميزة خلقة ابن آدم على غيره من المخلوقات.\nوَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِۚ\nيعني: المستلذات؛ لأنه جاء ذكر الطيبات في معرض الإنعام، فيراد به المستلذات، وإذا جاء في معرض التحليل والتحريم فيراد به الحلال والحرام. ابن جزي:٢/٢٨٤.\nورود لفظ (الطيبات) في القرآن يأتي على معنيَين، اذكرهما مع التوضيح.\nوَأُمِرۡتُ أَنۡ أُسۡلِمَ لِرَبِّ ٱلۡعَٰلَمِينَ ٦٦\nأذل وأخضع لرب العالمين. القرطبي:١٨/٣٧٨.\nكيف يتحقق الإسلام لله تعالى؟"],[475,"§غافر\nwords\nعَلَقَةٍالدَّمِ الغَلِيظِ؛ المُتَعَلِّقِ بِجِدَارِ الرَّحِمِ، وَهُوَ أَحَدُ أَطوَارِ الجَنِينِ.\nلِتَبلُغُوا أَشُدَّكُملِتَتَكَامَلَ قُوَّتُكُم.\nأَنَّى يُصرَفُونَكَيفَ يَعدِلُونَ عَنهَا مَع صِحَّتِهَا؟!\nيُسجَرُونَيُوقَدُ عَلَيهِم.\nضَلُّوا عَنَّاغَابُوا عَن عُيُونِنَا.\nتَمرَحُونَتَتَوَسَّعُونَ فِي الفَرَحِ أَشَرًا وَبَطَرًا.\nمَثوَىمَأوَى، وَمَسكَنُ.\ndeeds\nاستعذ بالله أن ترد إلى أرذل العمر.\nأقرأ قصص الأنبياء من صحيح مسلم.\nتأمل رجلًا غافلًا اُبتلي بعملٍ فاسد؛ وهو يفرح به، واحمد الله على أن عافاك من ذلك.\nguid\nسوء حشر المجادلين لإبطال الحق.\nإذا انتشر في البلد الفرح بالباطل؛ فهنا يُخشى من العقوبة.\nاصبر عن معاصي الله، وعلى طاعة الله، وعلى أقدار الله؛ فالفرج قريب.\nrefl\nإِذِ ٱلۡأَغۡلَٰلُ فِيٓ أَعۡنَٰقِهِمۡ وَٱلسَّلَٰسِلُ يُسۡحَبُونَ ٧١\nقال الحسن بن أبي الحسن: \"لم تجعل السلاسل في أعناق أهل النار لأنهم أعجزوا الرب! لكن لتُرسِبَهُمْ إذا أَطْفَاهُم اللهب\". ابن عطية:٤/٥٦٩.\nلمَ جعلت السلاسل في أعناق أهل النار؟\nفِي ٱلۡحَمِيمِ ثُمَّ فِي ٱلنَّارِ يُسۡجَرُونَ ٧٢\nهذا من قولك: سجرت التنور: إذا ملأته بالنار؛ فالمعنى: أنهم يدخلون فيها كما يدخل الحطب في التنور، ولذلك قال مجاهد في تفسيره: \"توقد بهم النار\". ابن جزي:٢/٢٨٥.\nكيف نستدل بهذه الآيات على خطورة الجدال في آيات الله بغير علم؟\nثُمَّ قِيلَ لَهُمۡ أَيۡنَ مَا كُنتُمۡ تُشۡرِكُونَ ٧٣ مِن دُونِ ٱللَّهِۖ قَالُواْ ضَلُّواْ عَنَّا بَل لَّمۡ نَكُن نَّدۡعُواْ مِن قَبۡلُ شَيۡـٔٗاۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ ٱلۡكَٰفِرِينَ ٧٤\n﴿ثُمَّ قِيلَ لَهُمۡ أَيۡنَ مَا كُنتُمۡ تُشۡرِكُونَ﴾ بعبادتكم إياها من دون الله من آلهتكم وأوثانكم حتى يغيثوكم؛ فينقذوكم مما أنتم فيه من البلاء والعذاب؛ فإن المعبود يغيث مَن عبده وخدمه. وإنَّما يقال هذا لهم توبيخًا وتقريعًا على ما كان منهم في الدنيا. الطبري:٢١/٤١٦.\nما الغاية من سؤال المشركين عن آلهتهم وهم يواجهون العذاب؟\nثُمَّ قِيلَ لَهُمۡ أَيۡنَ مَا كُنتُمۡ تُشۡرِكُونَ ٧٣\nوالاستفهام هنا مستعمل في التنبيه على الغلط والفضيحة في الموقف؛ فإنهم كانوا يزعمون أنهم يعبدون الأصنام ليكونوا شفعاء لهم من غضب الله، فلمّا حق عليهم العذاب فلم يجدوا شفعاء ذكروا بما كانوا يزعمونه، فقيل لهم: ﴿أَيۡنَ مَا كُنتُمۡ تُشۡرِكُونَ﴾. ابن عاشور:٢٤/٢٠٤.\nما فائدة الاستفهام في الآية الكريمة؟\nذَٰلِكُم بِمَا كُنتُمۡ تَفۡرَحُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَبِمَا كُنتُمۡ تَمۡرَحُونَ ٧٥\nذلكم العذاب بما كنتم تفرحون بالمعاصي؛ يقال لهم ذلك توبيخًا؛ أي: إنَّما نالكم هذا بما كنتم تظهرون في الدنيا من السرور بالمعصية، وكثرة المال والأتباع والصحة. القرطبي:١٨/٣٨٣.\nما سبب نزول العقوبة بهم؟ وما العبرة لنا في ذلك؟\nذَٰلِكُم بِمَا كُنتُمۡ تَفۡرَحُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَبِمَا كُنتُمۡ تَمۡرَحُونَ ٧٥\nأي: تفرحون بالباطل الذي أنتم عليه؛ وهذا هو الفرح المذموم الموجب للعقاب، بخلاف الفرح الممدوح الذي قال الله فيه: ﴿قُلۡ بِفَضۡلِ ٱللَّهِ وَبِرَحۡمَتِهِۦ فَبِذَٰلِكَ فَلۡيَفۡرَحُواْ﴾ [يونس: ٥٨]؛ وهو الفرح بالعلم النافع والعمل الصالح. السعدي:٧٤٣.\nما الفرح الممدوح؟ وما الفرح المذموم؟\nفَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۚ فَإِمَّا نُرِيَنَّكَ بَعۡضَ ٱلَّذِي نَعِدُهُمۡ أَوۡ نَتَوَفَّيَنَّكَ فَإِلَيۡنَا يُرۡجَعُونَ ٧٧\nإن أريناك بعض الذي نعدهم من العذاب قرّت عينك بذلك، وإن توفيناك قبل ذلك فإلينا يرجعون، فننتقم منهم أشد الانتقام. ابن جزي:٢/٢٨٦.\nفي قوله: ﴿فَإِمَّا نُرِيَنَّكَ﴾ تسلية للنبي -صلى الله عليه وسلم-؛ بيّن ذلك."],[476,"§غافر\nwords\nقُضِيَ بِالحَقِّحُكِمَ بِالعَدلِ بَينَ الرُّسُلِ، وَمُكَذِّبِيهِم.\nحَاجَةً فِي صُدُورِكُمأَمرًا ذَا بَالٍ تَهتَمُّونَ بِهِ.\nفَمَا أَغنَى عَنهُمفَمَا دَفَعَ عَنهُم.\nوَحَاقَنَزَلَ وَأَحَاطَ.\nبَأسَنَاعَذَابَنَا.\nخَلَتمَضَت.\ndeeds\nقُصَّ على زملائك أو إخوانك قصة من قصص القرآن.\nاحمد الله تعالى، واشكره على ما سخر من الانتفاع المتنوع من الدواب.\nتأمل صور آثار الأقوام الذين أهلكهم الله، ثم استغفر الله على تقصيرك وذنوبك؛ لئلَّا يصيبك ما أصابهم.\nguid\nالاتعاظ والاعتبار بما قص الله تعالى من أخبار الرسل.\nاعلم أن مآل الباطل إلى خسار مهما اشتهر وأعجب به الناس.\nالدين الصحيح يبنى على الوحي الصحيح، لا على البدع والخرافات.\nrefl\nوَلَكُمۡ فِيهَا مَنَٰفِعُ وَلِتَبۡلُغُواْ عَلَيۡهَا حَاجَةٗ فِي صُدُورِكُمۡ وَعَلَيۡهَا وَعَلَى ٱلۡفُلۡكِ تُحۡمَلُونَ ٨٠\nفالمنافع في هذه الآية أريد بها ما قابل منافع أكل لحومها في قوله: ﴿وَمِنۡهَا تَأۡكُلُونَ﴾؛ مثل: الانتفاع بأوبارها، وألبانها، وأثمانها، وأعواضِها في الديَات والمهور، وكذلك الانتفاع بجلودها باتخاذها قبابًا وغيرَها، وبالجلوس عليها، وكذلك الانتفاع بجَمال مرآها في العيون في المسرح والمراح. ابن عاشور:٢٤/٢١٥-٢١٦.\nاذكر بعض المنافع المندرجة ضمن قوله تعالى: ﴿وَلَكُمۡ فِيهَا مَنَٰفِعُ﴾.\nأَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ\n(فينظروا) نظر فكر واستدلال، لا نظر غفلة وإهمال. السعدي:٧٤٤.\nمتى يكون المرور على آثار الأقوام الذين أهلكهم الله مفيدًا؟ ومتى يكون مضرًا؟\nفَلَمَّا جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَرِحُواْ بِمَا عِندَهُم مِّنَ ٱلۡعِلۡمِ\nوهذا عام لجميع العلوم التي نوقض بها ما جاءت به الرسل، ومن أحقها بالدخول في هذا: علوم الفلسفة والمنطق اليوناني، الذي رُدَّت به كثير من آيات القرآن، ونقصت قدره من القلوب، وجعلت أدلته اليقينية القاطعة أدلة لفظية لا تفيد شيئًا من اليقين، ويقدَّم عليها عقول أهل السفه والباطل؛ وهذا من أعظم الإلحاد في آيات الله والمعارضة لها والمناقضة. السعدي:٧٤٤.\nمتى تكون بعض العلوم مذمومة؟ تحدث عن ذلك في ضوء الآية.\nفَلَمَّا جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَرِحُواْ بِمَا عِندَهُم مِّنَ ٱلۡعِلۡمِ\nالضمير يعود على الأمم المكذبين، وفي تفسير علمهم وجوه؛ أحدها: أنه ما كانوا يعتقدون من أنهم لا يبعثون ولا يحاسبون. والثاني: أنه علمهم بمنافع الدنيا ووجوه كسبها. والثالث: أنه علم الفلاسفة الذين يحتقرون علوم الشرائع. ابن جزي:٢/٢٨٦.\nفي هذه الآية دليل على أن من العلم ما يكون وبالًا على صاحبه، اذكر أمثلة على ذلك.\nفَلَمَّا جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَرِحُواْ بِمَا عِندَهُم مِّنَ ٱلۡعِلۡمِ\nسمي ذلك علمًا على ما يدَّعونه ويزعمونه؛ وهو في الحقيقة جهل. القرطبي:١٨/٥٥.\nهل يسمى ما عند هؤلاء المكذبين علمًا؟\nفَلَمَّا رَأَوۡاْ بَأۡسَنَا قَالُوٓاْ ءَامَنَّا بِٱللَّهِ وَحۡدَهُۥ وَكَفَرۡنَا بِمَا كُنَّا بِهِۦ مُشۡرِكِينَ ٨٤\nحكى حالة بعضهم ممن آمن بعد تلبس العذاب بهم، فلم ينفعهم ذلك. وفي ذكر هذا حض للعرب على المبادرة، وتخويف من التأني؛ لئلَّا يدركهم عذاب لا تنفعهم توبة بعد تلبسه بهم. ابن عطية:٤/٥٧٢.\nما الفائدة من إخبار قريش بعدم نفع إيمان من قبلهم بعد تلبس العذاب بهم؟\nفَلَمۡ يَكُ يَنفَعُهُمۡ إِيمَٰنُهُمۡ لَمَّا رَأَوۡاْ بَأۡسَنَاۖ سُنَّتَ ٱللَّهِ ٱلَّتِي قَدۡ خَلَتۡ فِي عِبَادِهِۦۖ\nأي: سن الله -عز وجل- في الكفار أنه لا ينفعهم الإيمان إذا رأوا العذاب... وأن التوبة لا تقبل بعد رؤية العذاب وحصول العلم الضروري. القرطبي:١٨/٣٨٦.\nاذكر سنة من سنن الله تعالى في خلقه ذكرتها هذه الآية."],[477,"§فصلت\nwords\nفُصِّلَتبُيِّنَت آيَاتُهُ، وَوُضِّحَت مَعَانِيهِ.\nأَكِنَّةٍأَغطِيَةٍ مَانِعَةٍ مِن فَهمِ مَا تَدعُونَا إِلَيهِ.\nوَقرٌصَمَمٌ، وَثِقَلٌ.\nفَاستَقِيمُوا إِلَيهِاسلُكُوا الطَّرِيقَ المُوصِلَ إِلَيهِ.\nغَيرُ مَمنُونٍغَيرُ مَقطُوعٍ، وَلاَ مَمنُوعٍ.\nأَندَادًاشُرَكَاءَ، وَنُظَرَاءَ.\nرَوَاسِيَجِبَالًا ثَوَابِتَ.\nأَقوَاتَهَاأَرزَاقَ أَهلِهَا.\ndeeds\nألح على الله سبحانه أن يصلح قلبك.\nأكثر من الاستغفار اليوم اقتداء بنبيك -صلى الله عليه وسلم- الذي كان يستغفر في اليوم أكثر من مائة مرة.\nتصدق بشيء من مالِك، واستعذ بالله من شر فتنة المال.\nguid\nأهمية تعلم اللغة العربية لكل مسلم يريد أن يفهم كلام الله.\nعندما تعظ الناس أو تنصح أحدًا فليكن كلامك مشتملًا على ترغيب وترهيب.\nراحتك تكون في الاستقامة على طاعة الله تعالى وكثرة الاستغفار كما أمرك الله.\nrefl\nتَنزِيلٞ مِّنَ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ ٢\nمن أعظم رحمته وأجلّها: إنزال هذا الكتاب الذي حصل به من العلم والهدى والنور والشفاء والرحمة والخير الكثير ما هو من أجلِّ نعمه على العباد. السعدي:٧٤٤.\nبيّن أعظم مظاهر رحمة الله على هذه الأمة.\nكِتَٰبٞ فُصِّلَتۡ ءَايَٰتُهُۥ\nأي: فُصِّل كل شيء من أنواعه على حدته؛ وهذا يستلزم البيان التام، والتفريق بين كل شيء، وتمييز الحقائق. السعدي:٧٤٤.\nماذا تستفيد من قوله تعالى: ﴿فُصِّلَتۡ ءَايَٰتُهُۥ﴾؟\nبَشِيرٗا وَنَذِيرٗا فَأَعۡرَضَ أَكۡثَرُهُمۡ فَهُمۡ لَا يَسۡمَعُونَ ٤\nنفي لسمعهم النافع الذي يعتد به. ابن عطية:٥/٤.\nما السمع المنفي عن هؤلاء الكفرة؟\nوَقَالُواْ قُلُوبُنَا فِيٓ أَكِنَّةٖ مِّمَّا تَدۡعُونَآ إِلَيۡهِ وَفِيٓ ءَاذَانِنَا وَقۡرٞ وَمِنۢ بَيۡنِنَا وَبَيۡنِكَ حِجَابٞ فَٱعۡمَلۡ إِنَّنَا عَٰمِلُونَ ٥\nوذلك الحجاب هو اختلافهم في الدين؛ لأن دينهم كان عبادة الأوثان، ودين محمد -صلى الله عليه وسلم- عبادة الله وحده لا شريك له؛ فذلك هو الحجاب الذي زعموا أنه بينهم وبين نبي الله. الطبري:٢١/٤٢٩.\nزعم الكفار أن بينهم وبين المرسل إليهم حجابًا، فما هو؟\nقُلۡ إِنَّمَآ أَنَا۠ بَشَرٞ مِّثۡلُكُمۡ يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞ فَٱسۡتَقِيمُوٓاْ إِلَيۡهِ وَٱسۡتَغۡفِرُوهُۗ وَوَيۡلٞ لِّلۡمُشۡرِكِينَ ٦\nأي: لست بملك، بل أنا من بني آدم. قال الحسن: \"علمه الله تعالى التواضع\". القرطبي:١٨/٣٩٢.\nبيّن ما يدل على أهمية التواضع من معنى الآية.\nٱلَّذِينَ لَا يُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡأٓخِرَةِ هُمۡ كَٰفِرُونَ ٧\nفإن قلت: لمَ خص من بين أوصاف المشركين منع الزكاة مقرونًا بالكفر بالآخرة؟ قلت: لأن أحب شيء إلى الإنسان ماله؛ وهو شقيق روحه، فإذا بذله في سبيل الله فذلك أقوى دليل على ثباته واستقامته وصدق نيته ونصوع طويته؛ ألا ترى إلى قوله -عز وجل-: ﴿وَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمُ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ وَتَثۡبِيتٗا مِّنۡ أَنفُسِهِمۡ﴾ [البقرة: ٢٦٥] أي: يثبتون أنفسهم، ويدلون على ثباتها بإنفاق الأموال. القرطبي:١٨/٣٩٣.\nلمَ قُرن ذكر منع الزكاة مع الكفر بالآخرة؟\n۞قُلۡ أَئِنَّكُمۡ لَتَكۡفُرُونَ بِٱلَّذِي خَلَقَ ٱلۡأَرۡضَ فِي يَوۡمَيۡنِ وَتَجۡعَلُونَ لَهُۥٓ أَندَادٗاۚ ذَٰلِكَ رَبُّ ٱلۡعَٰلَمِينَ ٩ وَجَعَلَ فِيهَا رَوَٰسِيَ مِن فَوۡقِهَا وَبَٰرَكَ فِيهَا وَقَدَّرَ فِيهَآ أَقۡوَٰتَهَا فِيٓ أَرۡبَعَةِ أَيَّامٖ سَوَآءٗ لِّلسَّآئِلِينَ ١٠\nالحكمة في خلقه هذه المخلوقات في مدة ممتدة مع قدرة الله على إيجادها في حين واحد... ليعلّم عباده التأني في الأمور والمهل. ابن عطية:٥/٥.\nما الحكمة في خلق السموات والأرض وما فيهما في مدة ممتدة مع قدرة الله على إيجادها في حين واحد؟"],[478,"§فصلت\nwords\nفَقَضَاهُنَّفَخَلَقَهُنَّ، وَأَبدَعَهُنَّ.\nبِمَصَابِيحَبِنُجُومٍ مُضِيئَةٍ.\nصَاعِقَةًعَذَابًا هَائِلًا.\nصَرصَرًاشَدِيدَةَ البُرُودَةِ، عَالِيَةَ الصَّوتِ.\nنَحِسَاتٍمَشؤُومَاتٍ.\nالهُونِالمُهِينِ.\nيُوزَعُونَيُرَدُّ أَوَّلُهُم عَلَى آخِرِهِم.\ndeeds\nاقرأ أو اسأل عن أسباب هلاك إحدى الأمم الماضية.\nاستعذ بالله من الغرور والكبر.\nإذا رأيت ريحًا مقبلةً فقل: \"اللهم إني أسألك خيرها، وخير ما فيها، وخير ما أرسلت به، وأعوذ بك من شرها، وشر ما فيها، وشر ما أرسلت به\".\nguid\nاحذر الإعراض والتولي عن طاعة الله؛ فذلك سبب نزول العذاب.\nلا مصيبة إلا بذنب أي: من الذنوب.\nلا تعاقب أحدًا قبل أن تخبره بذنبه الذي استحق به العقوبة.\nrefl\nإِذۡ جَآءَتۡهُمُ ٱلرُّسُلُ مِنۢ بَيۡنِ أَيۡدِيهِمۡ وَمِنۡ خَلۡفِهِمۡ أَلَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَۖ قَالُواْ لَوۡ شَآءَ رَبُّنَا لَأَنزَلَ مَلَٰٓئِكَةٗ فَإِنَّا بِمَآ أُرۡسِلۡتُم بِهِۦ كَٰفِرُونَ ١٤\nوقوله: ﴿مِّنۢ بَيۡنِ أَيۡدِيهِمۡ وَمِنۡ خَلۡفِهِمۡ﴾ تمثيل لحرص رسول كل منهم على هداهم؛ بحيث لا يترك وسيلة يتوسل بها إلى إبلاغهم الدين إلا توسل بها، فمُثِّل ذلك بالمجيء إلى كل منهم؛ تارة من أمامه، وتارة من خلفه؛ لا يترك له جهة، كما يفعل الحريص على تحصيل أمرٍ أَن يتطلبه، ويعيد تطلبه، ويستوعب مظانّ وجوده أو مظانّ سماعه. ابن عاشور: ٢٤/٢٥٣.\nبيّن حرص الرسل على تبليغ الدين من خلال الآية الكريمة.\nقَالُواْ لَوۡ شَآءَ رَبُّنَا لَأَنزَلَ مَلَٰٓئِكَةٗ فَإِنَّا بِمَآ أُرۡسِلۡتُم بِهِۦ كَٰفِرُونَ ١٤\nوهذه الشبهة لم تزل متوارثة بين المكذبين من الأمم، وهي من أوهى الشبه؛ فإنه ليس من شرط الإرسال أن يكون المرسل مَلَكًا، وإنَّما شرط الرسالة أن يأتي الرسول بما يدل على صدقه؛ فليقدحوا إن استطاعوا بصدقه بقادح عقلي أو شرعي، ولن يستطيعوا إلى ذلك سبيلًا. السعدي: ٧٤٦.\nبيّن تشابه حجج الكافرين من خلال الآية.\nفَأَمَّا عَادٞ فَٱسۡتَكۡبَرُواْ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَقَالُواْ مَنۡ أَشَدُّ مِنَّا قُوَّةًۖ\nاغتروا بأجسامهم حين تهددهم بالعذاب، وقالوا: نحن نقدر على دفع العذاب عن أنفسنا بفضل قوتنا؛ وذلك أنهم كانوا ذوي أجسام طوال وخلق عظيم. القرطبي: ١٨/٤٠١.\nبم اغتر قوم هود حين جاءهم أمر الله؟ وهل نفعهم ذلك؟\nوَأَمَّا ثَمُودُ فَهَدَيۡنَٰهُمۡ\nوإنَّما نص عليهم -وإن كان جميع الأمم المهلكة قد قامت عليهم الحجة وحصل لهم البيان-؛ لأن آية ثمود آية باهرة، قد رآها صغيرهم وكبيرهم، وذكرهم وأنثاهم، وكانت آية مبصرة؛ فلهذا خصهم بزيادة البيان والهدى. السعدي: ٧٤٧.\nلماذا خصت ثمود بذكر الهداية مع أن الله تعالى دعا جميع البشر للهداية؟\nوَأَمَّا ثَمُودُ فَهَدَيۡنَٰهُمۡ فَٱسۡتَحَبُّواْ ٱلۡعَمَىٰ عَلَى ٱلۡهُدَىٰ\nهذا كما هي الآن شريعة الإسلام مبينة لليهود والنصارى المختلطين لنا، ولكنهم يعرضون ويشتغلون بالصد؛ فذلك استحباب العمى على الهدى. ابن عطية: ٥/١٠.\nما المراد باستحباب العمى على الهدى المذكور في الآية؟\nوَيَوۡمَ يُحۡشَرُ أَعۡدَآءُ ٱللَّهِ إِلَى ٱلنَّارِ فَهُمۡ يُوزَعُونَ ١٩\nيساقون ويدفعون إلى جهنم؛ قال قتادة والسدي: \"يحبس أولهم عن آخرهم حتى يجتمعوا\"، قال أبو الأحوص: \"فإذا تكاملت العدة بُدئ بالأكابر فالأكابر جرمًا\". القرطبي: ١٨/٤٠٥.\nبيّن كيف يساق أعداء الله إلى النار -والعياذ بالله-.\nحَتَّىٰٓ إِذَا مَا جَآءُوهَا شَهِدَ عَلَيۡهِمۡ سَمۡعُهُمۡ وَأَبۡصَٰرُهُمۡ وَجُلُودُهُم بِمَا كَانُواْ يَعۡمَلُونَ ٢٠\nوخص هذه الأعضاء الثلاثة؛ لأن أكثر الذنوب إنَّما تقع عليها أو بسببها. السعدي: ٧٤٧.\nلماذا خصت هذه الأعضاء الثلاثة بالذكر دون غيرها؟"],[479,"§فصلت\nwords\nتَستَتِرُونَتَستَخفُونَ عِندَ ارتِكَابِكُمُ المَعَاصِيَ.\nمَثوىًمَأوىً وَمَسكَنٌ.\nيَستَعتِبُوايَطلُبُوا العُتبَى وَهِيَ المَغفِرَةُ.\nفَمَا هُم مِنَ المُعتَبِينَمَا هُم مِنَ المُجَابِينَ إِلَى مَا طَلَبُوا.\nوَقَيَّضنَاهَيَّأنَا.\ndeeds\nحدد من يزين لك فعل السوء واحذر من مجالسته.\nألح على الله تعالى بالدعاء أن يرزقك جليسًا صالحًا، وأن يصرف عنك جُلساء السوء.\nاستمع إلى أحد المشايخ المجيدين في قراءة القرآن متدبرًا الآيات.\nguid\nأحسن الظن بالله مخالفةً لظن المشركين به.\nمن الناس من يصبر في سبيل طاعة الله، ومن الناس من يصبر في سبيل معصية الله.\nإذا خالفت أوامر المتبوعين أوامر الله هلكوا وأهلكوا من يتبعهم.\nrefl\nوَمَا كُنتُمۡ تَسۡتَتِرُونَ أَن يَشۡهَدَ عَلَيۡكُمۡ سَمۡعُكُمۡ وَلَآ أَبۡصَٰرُكُمۡ وَلَا جُلُودُكُمۡ\nفي معناه وجهان؛ أحدهما: لم تقدروا أن تستتروا من سمعكم وأبصاركم وجلودكم؛ لأنها ملازمة لكم، فلم يمكنكم احتراس من ذلك، فشهدت عليكم. والآخر: لم تتحفظوا من شهادة سمعكم وأبصاركم وجلودكم؛ لأنكم لم تبالوا بشهادتها، ولم تظنوا أنها تشهد عليكم. ابن جزي: ٢/٢٩١.\nما المراد بقوله: (تستترون)؟ وما الفائدة التي تؤخذ من هذه الآية؟\nوَذَٰلِكُمۡ ظَنُّكُمُ ٱلَّذِي ظَنَنتُم بِرَبِّكُمۡ أَرۡدَىٰكُمۡ فَأَصۡبَحۡتُم مِّنَ ٱلۡخَٰسِرِينَ ٢٣\nقال الحسن البصري: \"إن قومًا ألهتهم الأماني حتى خرجوا من الدنيا وما لهم من حسنة، ويقول أحدهم: إني أحسن الظن بربي. وكذب؛ ولو أحسن الظن لأحسن العمل\". القرطبي: ١٨/٤٠٩- ٤١٠.\nبيّن متى يكون حسن الظن بالله في غير محله.\n۞وَقَيَّضۡنَا لَهُمۡ قُرَنَآءَ فَزَيَّنُواْ لَهُم مَّا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ\nأي: هيأنا لهم شياطين، وقيل: سلَّطنا عليهم قرناء يزينون عندهم المعاصي، وهؤلاء القرناء من الجن والشياطين، ومن الإنس أيضًا. القرطبي: ١٨/٤١١.\nبينت الآية علامة إرادة الشر بالعبد، فما هي؟\nوَقَالَ ٱلَّذِينَ كَفَرُواْ لَا تَسۡمَعُواْ لِهَٰذَا ٱلۡقُرۡءَانِ وَٱلۡغَوۡاْ فِيهِ لَعَلَّكُمۡ تَغۡلِبُونَ ٢٦\nوهذا من شأن دعاة الضلال والباطل: أن يُكَمِّموا أفواه الناطقين بالحق والحجة بما يستطيعون من تخويف وتسويل، وترهيب وترغيب، ولا يَدعوا الناس يتجادلون بالحجة، ويتراجعون بالأدلة؛ لأنهم يوقنون أن حجة خصومهم أنهَضُ، فهم يسترونها ويدافعونها لا بمثلها؛ ولكن بأساليب من البهتان والتضليل، فإذا أعيتهم الحِيَل ورأوا بوارق الحق تخفق؛ خَشُوا أن يعُمَّ نورُها الناسَ الذين فيهم بقية من خير ورشد، عدلوا إلى لغو الكلام، ونفخوا في أبواق اللغو. ابن عاشور: ٢٤/٢٧٧.\nبيّن من الآية الكريمة صفة من صفات أهل الضلال في صد الحق.\nوَقَالَ ٱلَّذِينَ كَفَرُواْ لَا تَسۡمَعُواْ لِهَٰذَا ٱلۡقُرۡءَانِ وَٱلۡغَوۡاْ فِيهِ لَعَلَّكُمۡ تَغۡلِبُونَ ٢٦\nوهذه شهادة من الأعداء، وأوضح الحق ما شهدت به الأعداء؛ فإنهم لم يحكموا بغلبتهم لمن جاء بالحق إلا في حال الإعراض عنه والتواصي بذلك، ومفهوم كلامهم: أنهم إن لم يلغوا فيه، بل استمعوا إليه، وألقوا أذهانهم أنهم لا يَغلِبُون. السعدي: ٧٤٨.\nفي الآية شهادة من الكفار للحق، ما وجه هذه الشهادة؟\nوَقَالَ ٱلَّذِينَ كَفَرُواْ لَا تَسۡمَعُواْ لِهَٰذَا ٱلۡقُرۡءَانِ وَٱلۡغَوۡاْ فِيهِ لَعَلَّكُمۡ تَغۡلِبُونَ ٢٦\nقال ابن عباس -رضي الله عنهما-: \"يعني الغطوا فيه، وكان بعضهم يوصي إلى بعض: إذا رأيتم محمدًا يقرأ فعارضوه بالرجز والشعر واللغو\"، قال مجاهد: \"والغوا فيه بالمكاء والصفير\"، وقال الضحاك: \"أكثروا الكلام؛ فيختلط عليه ما يقول\". القرطبي: ٤/٦٥.\nفي الآية بيان لبعض أساليب المفسدين في منع الإفادة من الذكر والمواعظ، وضحها.\nوَقَالَ ٱلَّذِينَ كَفَرُواْ رَبَّنَآ أَرِنَا ٱلَّذَيۡنِ أَضَلَّانَا مِنَ ٱلۡجِنِّ وَٱلۡإِنسِ نَجۡعَلۡهُمَا تَحۡتَ أَقۡدَامِنَا لِيَكُونَا مِنَ ٱلۡأَسۡفَلِينَ ٢٩\nثم ذكر -عز وجل- مقالة كفار يوم القيامة إذا دخلوا النار؛ فإنهم يرون عظيم ما حل بهم وسوء منقلبهم، فتجول أفكارهم فيمن كان سبب غوايتهم وبادي ضلالتهم، فيعظم غيظهم وحنقهم عليه، ويودون أن يحصل في أشد عذاب، فحينئذ يقولون: (ربنا أرنا اللذين أضلانا). ابن عطية: ٥/١٤.\nما الذي دفع أصحاب النار لطلب أن يكون تحت أقدامهم من أضلهم من الجن والإنس؟"],[480,"§فصلت\nwords\nاستَقَامُواثَبَتُوا عَلَى الحَقِّ؛ عِلمًا وَعَمَلًا.\nوَلِيٌّ حَمِيمٌقَرِيبٌ لَكَ، شَفِيقٌ عَلَيكَ.\nوَمَا يُلَقَّاهَامَا يُوَفَّقُ لَهَا.\nيَنزَغَنَّكَيُلقِيَنَّ فِي نَفسِكَ وَسوَسَةً، وَيَصرِفَنَّكَ عَنِ الخَيرِ.\nفَاستَعِذ بِاللهِاستَجِر، وَاعتَصِم بِاللهِ قَائِلًا: أَعُوذُ بِاللهِ مِنَ الشَّيطَانِ الرَّجِيمِ.\nلاَ يَسأَمُونَلاَ يَفتُرُونَ، وَلاَ يَمَلُّونَ.\ndeeds\nقدم هدية لأحدٍ بينك وبينه سوء تفاهم، وتأمل فِعلَ الهديةِ في إصلاح قلبيكما.\nإذا أحسست بنزغ الشيطان فاستعذ بالله منه.\nاسجد للتلاوة عند قراءة هذه الآية.\nguid\nالمؤمن يعرف مصيره في الآخرة عند خروج روحه من جسده.\nللمؤمن في الجنة كل ما تشتهيه الأنفس وتلذ الأعين.\nعوّد نفسك الصبر؛ فهو رأس الأخلاق الحسنة.\nrefl\nإِنَّ ٱلَّذِينَ قَالُواْ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَٰمُواْ تَتَنَزَّلُ عَلَيۡهِمُ ٱلۡمَلَٰٓئِكَةُ\nوجَمَع قولُه: ﴿قَالُواْ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَٰمُواْ﴾ أَصْلَيِ الكمال الإسلامي؛ فقوله: ﴿قَالُواْ رَبُّنَا ٱللَّهُ﴾ مشير إلى الكمال النفساني؛ وهو معرفة الحق للاهتداء به، ومعرفة الخير لأجل العمل به... وأشار قوله: ﴿ثُمَّ ٱسۡتَقَٰمُواْ﴾ إلى أساس الأعمال الصالحة؛ وهو الاستقامة على الحق. ابن عاشور: ٢٤/٢٨٣.\nكيف جمع قوله تعالى: ﴿قَالُواْ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَٰمُواْ﴾ أَصْلَيِ الكمال الإنساني؟\nإِنَّ ٱلَّذِينَ قَالُواْ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَٰمُواْ\nقال عمر بن الخطاب -رضي الله عنه-: \"الاستقامة: أن تستقيم على الأمر والنهي، ولا تروغ روغان الثعلب\"، وقال عثمان بن عفان -رضي الله عنه-: \"أخلصوا العمل لله\"، وقال علي -رضي الله عنه-: \"أدوا الفرائض\". البغوي: ٤/٦٥-٦٦.\nبيّن حقيقة الاستقامة المرادة في الآية.\nنَحۡنُ أَوۡلِيَآؤُكُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۖ\nأي: تقول لهم الملائكة الذين تتنزل عليهم بالبشارة: ﴿نَحۡنُ أَوۡلِيَآؤُكُمۡ﴾، قال مجاهد: \"أي نحن قرناؤكم الذين كنا معكم في الدنيا، فإذا كان يوم القيامة قالوا: لا نفارقكم حتى ندخلكم الجنة\". القرطبي: ١٨/٤١٨.\nبينت الآية فائدة يفيدها المؤمنون من عالم الملائكة، فما هي؟\nوَمَنْ أَحْسَنُ قَوۡلٗا مِّمَّن دَعَآ إِلَى ٱللَّهِ وَعَمِلَ صَٰلِحٗا وَقَالَ إِنَّنِي مِنَ ٱلۡمُسۡلِمِينَ ٣٣\nأي: دعا عباد الله إليه، وهو في نفسه مهتدٍ بما يقوله، فنفعُه لنفسه ولغيره؛ لازمٌ ومتعدٍ، وليس هو من الذين يأمرون بالمعروف ولا يأتونه، وينهون عن المنكر ويأتونه، بل يأتمر بالخير ويترك الشر، ويدعو الخلق إلى الخالق -تبارك وتعالى-. ابن كثير: ٤/١٠٢.\nللداعية الصادق علامة؛ فما هي؟\nوَمَا يُلَقَّىٰهَآ إِلَّا ٱلَّذِينَ صَبَرُواْ وَمَا يُلَقَّىٰهَآ إِلَّا ذُو حَظٍّ عَظِيمٍ٣٥\nأي: وما يوفق لهذه الخصلة الحميدة ﴿إِلَّا ٱلَّذِينَ صَبَرُواْ﴾ نفوسهم على ما تكره، وأجبروها على ما يحبه الله؛ فإن النفوس مجبولة على مقابلة المسيء بإساءته وعدم العفو عنه؛ فكيف بالإحسان؟! فإذا صبّر الإنسان نفسه، وامتثل أمر ربه، وعرف جزيل الثواب، وعلم أن مقابلته للمسيء بجنس عمله لا يفيده شيئًا، ولا يزيد العداوة إلا شدة، وأن إحسانه إليه ليس بواضع قدره، بل من تواضع لله رفعه؛ هان عليه الأمر، وفعل ذلك متلذذًا مستحليًا له. السعدي: ٧٤٩.\nلماذا لم تثبت هذه الحالة إلا للذين صبروا وذوي الحظ العظيم فقط؟\nوَمَا يُلَقَّىٰهَآ إِلَّا ٱلَّذِينَ صَبَرُواْ وَمَا يُلَقَّىٰهَآ إِلَّا ذُو حَظٍّ عَظِيمٍ٣٥\nلكونها من خصال خواص الخلق التي ينال بها العبد الرفعة في الدنيا والآخرة، التي هي من أكبر خصال مكارم الأخلاق. السعدي: ٧٤٩.\nبينت الآية علامة من علامات خواص الخلق عند الله، فما هي؟\nوَإِمَّا يَنْزَغَنَّكَ مِنَ الشَّيْطَانِ نَزْغٌ فَاسْتَعِذْ بِاللَّهِ إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ٣٦\nلما ذكر تعالى ما يقابل به العدو من الإنس -وهو مقابلة إساءته بالإحسان- ذكر ما يدفع به العدو الجني؛ وهو: الاستعاذة بالله، والاحتماء من شره. فقال: ﴿وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيۡطَٰنِ نَزۡغٌ﴾ أي: أيَّ وقت من الأوقات أحسست بشيء من نزغات الشيطان؛ أي: من وساوسه وتزيينه للشر، وتكسيله عن الخير، وإصابة ببعض الذنوب، وإطاعة له ببعض ما يأمر به؛ ﴿فَٱسۡتَعِذۡ بِٱللَّهِۚ﴾ أي: اسأله، مفتقرًا إليه، أن يعيذك ويعصمك منه. السعدي: ٧٥٠.\nكيف ندفع العدو من الجن؟"],[481,"§فصلت\nwords\nاهتَزَّتدَبَّت فِيهَا الحِيَاةُ، وَتَحَرَّكَت بِالنَّبَاتِ.\nوَرَبَتانتَفَخَت، وَعَلَت.\nيُلحِدُونَيَمِيلُونَ عَنِ الحَقِّ.\nوَقرٌصَمَمٌ.\nمُرِيبٍشَدِيدِ الرِّيبَةِ مُقلِقٍ.\ndeeds\nادع الله أن يحيي قلبك بالإيمان كما يحيي الأرض الميتة بالماء.\nأرسل رسالة تبشر فيها بقرب رحمة الله في كشف الضر وصلاح الأحوال.\nضع يدك على مكان ألمٍ، واقرأ ما تيسر لك من القرآن؛ فإنه شفاء.\nguid\nلا يأس من رحمة يصلح بها الله أحوال البلد، ويزيل بها المعاصي والفقر والخوف والحرب.\nشبهات الكفار والمنافقين والعلمانيين حول القرآن والدين متشابهة على مر القرون والأزمان.\nالقرآن دواء وشفاء لأهل الإيمان، وداء على أهل الكفر والنفاق.\nrefl\nإِنَّ ٱلَّذِينَ يُلۡحِدُونَ فِيٓ ءَايَٰتِنَا لَا يَخۡفَوۡنَ عَلَيۡنَآۗ\nفيه تهديد شديد، ووعيد أكيد، أي: أنه تعالى عالم بمن يلحد في آياته وأسمائه وصفاته، وسيجزيه على ذلك بالعقوبة والنكال. ابن كثير:٤/١٠٤.\nما المراد من إخبار الله عن هؤلاء الملحدين بأنهم لا يخفون عليه؟\nإِنَّ ٱلَّذِينَ كَفَرُواْ بِٱلذِّكۡرِ لَمَّا جَآءَهُمۡۖ وَإِنَّهُۥ لَكِتَٰبٌ عَزِيزٞ ٤١\nووصف تعالى الكتاب بالعزة؛ لأنه بصحة معانيه ممتنع الطعن فيه، والإزراء عليه، وهو محفوظ من الله تعالى. ابن عطية:٥/١٩.\nوضح فائدة وصف الله تعالى القرآن بأنه عزيز.\nمَّا يُقَالُ لَكَ إِلَّا مَا قَدۡ قِيلَ لِلرُّسُلِ مِن قَبۡلِكَۚ إِنَّ رَبَّكَ لَذُو مَغۡفِرَةٖ وَذُو عِقَابٍ أَلِيمٖ ٤٣\nووصف العقاب بـــ (أليم) دون وصف آخر؛ للإشارة إلى أنه مناسب لما عوقبوا لأجله؛ فإنهم آلموا نفس النبي -صلى الله عليه وسلم- بما عصوا وآذوا. ابن عاشور:٤/٣١١.\nما فائدة وصف العقاب بالأليم في الآية الكريمة؟\nإِنَّ رَبَّكَ لَذُو مَغۡفِرَةٖ وَذُو عِقَابٍ أَلِيمٖ ٤٣\nلولا عفو الله وتجاوزه ما هَنَّأَ أحدًا العيشُ، ولولا وعيده وعقابه لاتّكل كل أحد. ابن كثير:٤/١٠٤.\nلمَ جمعت كثير من الآيات بين المغفرة والعقاب كما في هذه الآية؟\nقُلۡ هُوَ لِلَّذِينَ ءَامَنُواْ هُدٗى وَشِفَآءٞۚ\nأَعلَمَ الله أن القرآن هدى وشفاء لكل من آمن به من الشك والريب والأوجاع. القرطبي:١٨/٤٣١.\nمن الذي يستفيد من هدى القرآن وشفائه؟\nوَٱلَّذِينَ لَا يُؤۡمِنُونَ فِيٓ ءَاذَانِهِمۡ وَقۡرٞ وَهُوَ عَلَيۡهِمۡ عَمًىۚ أُوْلَٰٓئِكَ يُنَادَوۡنَ مِن مَّكَانِۢ بَعِيدٖ ٤٤\nأي: إنهم لا يسمعون ولا يفهمون، كما أن من دُعي من مكان بعيد لم يسمع ولم يفهم، وهذا مثلٌ لقلة انتفاعهم بما يوعظون به؛ كأنهم ينادَون من حيث لا يسمعون. البغوي:٤/٧٠.\nما المقصد القرآني من ضرب هذا المثل: ﴿يُنَادَوۡنَ مِن مَّكَانِۭ بَعِيدٍ﴾؟\nوَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ فَٱخۡتُلِفَ فِيهِۚ وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ لَقُضِيَ بَيۡنَهُمۡۚ وَإِنَّهُمۡ لَفِي شَكّٖ مِّنۡهُ مُرِيبٖ ٤٥\nيقول: وإن الفريق المبطل منهم ﴿لَفِي شَكٍّ﴾ مما قالوا فيه. (مريب) يقول: يريبهم قولهم فيه ما قالوا؛ لأنهم قالوا بغير ثبت، وإنَّما قالوه ظنًّا. الطبري:٢١/٤٨٧.\nلماذا لا يثق الكفار فيما يصفون به القرآن الكريم؟"],[482,"§فصلت\nwords\nأَكمَامِهَاأَوعِيَتِهَا.\nآذَنَّاكَأَعلَمنَاكَ.\nمَحِيصٍمَلَجَإٍ، وَمَهرَبٍ.\nلاَ يَسأَمُلاَ يَمَلُّ.\nوَنَأَى بِجَانِبِهِتَبَاعَدَ عَن شُكرِ النِّعمَةِ، وَاتِّبَاعِ الحَقِّ؛ تَكَبُّرًا.\nفَذُو دُعَاءٍ عَرِيضٍصَاحِبُ دُعَاءٍ بِكَشفِ الضُّرِّ كَثِيرٍ.\nشِقَاقٍبَعِيدٍ خِلاَفٍ بَعِيدٍ عَنِ الحَقِّ.\ndeeds\nسل الله من واسع رزقه وأن يعلمك علمًا نافعًا.\nاقرأ بعض الآيات والأحاديث المتعلقة بالساعة.\nادع الله بتفريج همك.\nguid\nفي يوم القيامة يفترق كل داع عمن كان يدعوه، ويتبرأ كلٌّ من الآخر.\nضعف الإنسان حتى في عقله وتصوراته.\nالإنسان بلا إيمان من أضل المخلوقات.\nrefl\nلَّا يَسۡـَٔمُ ٱلۡإِنسَٰنُ مِن دُعَآءِ ٱلۡخَيۡرِ وَإِن مَّسَّهُ ٱلشَّرُّ فَيَـُٔوسٞ قَنُوطٞ ٤٩\nهذا إخبار عن طبيعة الإنسان من حيث هو، وعدم صبره وجَلَدِه؛ لا على الخير ولا على الشر، إلا مَن نقله الله من هذه الحال إلى حال الكمال. السعدي:٧٥٢.\nأنت ضعيف ببدنك وقلبك، بيِّن هذا من خلال الآية، وبيِّن كيفية العلاج.\nلَّا يَسۡـَٔمُ ٱلۡإِنسَٰنُ مِن دُعَآءِ ٱلۡخَيۡرِ وَإِن مَّسَّهُ ٱلشَّرُّ فَيَـُٔوسٞ قَنُوطٞ ٤٩ وَلَئِنۡ أَذَقۡنَٰهُ رَحۡمَةٗ مِّنَّا مِنۢ بَعۡدِ ضَرَّآءَ مَسَّتۡهُ لَيَقُولَنَّ هَٰذَا لِي وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةٗ وَلَئِن رُّجِعۡتُ إِلَىٰ رَبِّيٓ إِنَّ لِي عِندَهُۥ لَلۡحُسۡنَىٰۚ\nوصف الإنسان بأقبح صفتين: إن مسه الشر صار إلى حال القانط ووجم وجوم الآيس، فإذا مسه الخير نسي أن الله هو المنعم عليه المُفضِل بما أعطاه؛ فبطر وظن أنه هو المستحق لذلك، ثم أضاف إلى ذلك تكذيبه بالبعث فقال: ﴿وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةً﴾، ثم أضاف إلى ذلك ظنُّه الكاذب أنه إن بُعِث كان له عند الله الحسنى، فلم يدع هذا للجهل والغرور موضعًا. ابن القيم:٢/٤٢٠.\nما الصفتان القبيحتان اللتان يتصف بهما المرء حال تعرضه للشر والخير؟\nوَإِذَآ أَنۡعَمۡنَا عَلَى ٱلۡإِنسَٰنِ أَعۡرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ فَذُو دُعَآءٍ عَرِيضٍ ٥١\n﴿فَذُو دُعَآءٍ عَرِيضٍ﴾ أي: كثير جدًا؛ لعدم صبره، فلا صبر في الضراء، ولا شكر في الرخاء، إلا مَن هداه الله ومَنَّ عليه. السعدي:٧٥٢.\nما هي الحال التي يجب أن يكون عليها المؤمن في السراء أو في الضراء؟\nوَإِذَآ أَنۡعَمۡنَا عَلَى ٱلۡإِنسَٰنِ أَعۡرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ فَذُو دُعَآءٍ عَرِيضٍ ٥١\nوعدل عن إسناد إصابة الشر إلى الله تعليمًا للأدب مع الله؛ كما قال إبراهيم: ﴿ٱلَّذِي خَلَقَنِي فَهُوَ يَهۡدِينِ...﴾ إلخ... ثم قال: ﴿وَإِذَا مَرِضۡتُ فَهُوَ يَشۡفِينِ﴾ [الشعراء: ٧٨- ٨٠]؛ فلم يقل: \"وإذا أمرضني\". وفي ذلك سرٌّ: وهو أن النعم والخير مسخّران للإنسان في أصل وضع خلقته؛ فهما الغالبان عليه لأنّهما من مظاهر ناموس بقاء النوع، وأمّا الشرور والأضرار؛ فإن معظمها ينجرّ إلى الإنسان بسوء تصرفه، وبتعرضه إلى ما حذرته منه الشرائع والحكماء الملهمون؛ فقلّما يقع فيهما الإنسان إلا بعلمه وجُرأته. ابن عاشور:٢٥/١٥.\nلماذا عدلت الآية الكريمة عن إسناد إصابة الشر إلى الله تعالى؟ وكيف يصل الشر إلى الإنسان غالبًا؟\nسَنُرِيهِمۡ ءَايَٰتِنَا فِي ٱلۡأٓفَاقِ وَفِيٓ أَنفُسِهِمۡ حَتَّىٰ يَتَبَيَّنَ لَهُمۡ أَنَّهُ ٱلۡحَقُّ\nأي: أن القرآن حق؛ فأخبر أنه لا بد أن يريهم من آياته المشهودة ما يبين لهم أن آياته المتلوة حق. ابن القيم:٢/٤٢٠.\nآيات الله في الكون والنفس دالة على صحة القرآن، وضح ذلك من خلال الآية.\nسَنُرِيهِمۡ ءَايَٰتِنَا فِي ٱلۡأٓفَاقِ وَفِيٓ أَنفُسِهِمۡ حَتَّىٰ يَتَبَيَّنَ لَهُمۡ أَنَّهُ ٱلۡحَقُّ\nفـي هذه الآية طرف من الإعجاز بالإخبار عن الغيب إذ أخبرتْ بالوعد بحصول النصر له ولدينه؛ وذلك بما يسَّر الله لرسوله -صلى الله عليه وسلم- ولخلفائه مِن بعده -في آفاق الدّنيا والمشرق والمغرب عامة، وفي بَاحة العرب خاصة- من الفتوح وثباتها وانطباع الأمم بها ما لم تتيسر أمثالها لأحد من ملوك الأرض والقياصرة والأكاسرة على قلة المسلمين... والتاريخ شاهد بأن ما تهيأ للمسلمين من عجائب الانتشار والسلطان على الأمم أمر خارق للعادة؛ فيتبين أن دين الإسلام هو الحق، وأن المسلمين كلما تمسكوا بعُرى الإسلام لقوا من نصر الله أمرًا عجيبًا؛ يشهد بذلك السابق واللاحق. ابن عاشور: ٢٥/١٨.\nفي الآية الكريمة إعجاز غيبي؛ بيّنه.\nأَلَآ إِنَّهُمۡ فِي مِرۡيَةٖ مِّن لِّقَآءِ رَبِّهِمۡۗ\nإن عمر بن عبد العزيز -رضي الله عنه- صعد المنبر فحمد الله وأثنى عليه، ثم قال: \"أما بعد أيها الناس، فإني لم أجمعكم لأمر أُحدِثه فيكم، ولكن فكّرت في هذا الأمر الذي أنتم إليه صائرون؛ فعلمت أن المصدق بهذا الأمر أحمق، والمكذّب به هالك\"، ثم نزل. ومعنى قوله -رضي الله عنه-: (إن المصدق به أحمق) أي: لأنه لا يعمل له عمل مثله، ولا يحذر منه، ولا يخاف من هوله، وهو مع ذلك مصدق به، موقن بوقوعه، وهو مع ذلك يتمادى في لعبه وغفلته وشهواته وذنوبه؛ فهو أحمق بهذا الاعتبار، والأحمق في اللغة ضعيف العقل. ابن كثير:٤/١٠٧.\nبعض الذين يصدقون بيوم القيامة ينبئ حالهم بأنهم في مرية وشك منه؛ بَيِّن ذلك."],[483,"§الشورىٰ\nwords\nيَتَفَطَّرنَيَتَشَقَّقنَ.\nأَولِيَاءَآلِهَةً يَتَوَلَّونَهَا، وَيَعبُدُونَهَا.\nحَفِيظٌرَقِيبٌ عَتِيدٌ.\nأُمَّ القُرَىمَكَّةَ؛ وَالمُرَادُ أَهلُهَا.\nلاَ رَيبَ فِيهِلاَ شَكَّ فِي مَجِيئِهِ.\nأُمَّةً وَاحِدَةًمُجتَمِعِينَ عَلَى الهُدَى.\nوَإِلَيهِ أُنِيبُإِلَيهِ أَرجِعُ فِي كُلِّ الأُمُورِ.\ndeeds\nاستغفر لنفسك ولأهل الأرض من المؤمنين والمؤمنات اقتداءً بالملائكة.\nألق موعظة على جماعة المسجد أو أرسل رسالة عن يوم القيامة.\nانظر مسألة اختلف فيها من حولك، وابحث عن حكم الله فيها، وذكرهم به مع ذكر الدليل.\nguid\nالمؤمن يحمل هم إخوانه المؤمنين.\nأفضل مصدر للمواعظ والدروس هو القرآن الكريم.\nستبقى اللغة العربية مفتاحًا لتعلم الدين الصحيح؛ فاحرص على تعلمها.\nrefl\nكَذَٰلِكَ يُوحِيٓ إِلَيۡكَ وَإِلَى ٱلَّذِينَ مِن قَبۡلِكَ ٱللَّهُ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ٣\nوإجراء وصفي: ﴿ٱلۡعَزِيزُ ٱلۡحَكِيمُ﴾ على اسم الجلالة دون غيرهما؛ لأن لهاتين الصفتين مزيد اختصاص بالغرض المقصود من أن الله يصطفي من يشاء لرسالته. ابن عاشور:٢٥/٢٧.\nما وجه ختم الآية بصفتي: ﴿ٱلۡعَزِيزُ ٱلۡحَكِيمُ﴾؟\nتَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرۡنَ مِن فَوۡقِهِنَّۚ\nأي: تكاد كل واحدة منها تنفطر فوق التي تليها من قول المشركين: ﴿ٱتَّخَذَ ٱللَّهُ وَلَدًاۗ﴾. القرطبي:١٨/٤٤٤.\nمن أي شيء تكاد تنفطر السماوات؟\nتَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرۡنَ مِن فَوۡقِهِنَّۚ وَٱلۡمَلَٰٓئِكَةُ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ\nوتقديم التسبيح على الحمد إشارة إلى أن تنزيه الله عمّا لا يليق به أهم من إثبات صفات الكمال له؛ لأن التنزيه تمهيد لإدراك كمالاته تعالى. ابن عاشور:٢٥/٣٣.\nما فائدة تقديم التسبيح على الحمد؟\nوَٱلۡمَلَٰٓئِكَةُ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ وَيَسۡتَغۡفِرُونَ لِمَن فِي ٱلۡأَرۡضِۗ\nيسألون ربهم المغفرة لذنوب من في الأرض من أهل الإيمان به. الطبري:٢١/٥٠٢.\nأقرب الخلق من الله سبحانه أرحمهم بالخلق، وضح ذلك من الآية.\nوَمَا ٱخۡتَلَفۡتُمۡ فِيهِ مِن شَيۡءٖ فَحُكۡمُهُۥٓ إِلَى ٱللَّهِۚ\nومفهوم الآية الكريمة: أن اتفاق الأمة حجة قاطعة؛ لأن الله تعالى لم يأمرنا أن نرد إليه إلا ما اختلفنا فيه، فما اتفقنا عليه يكفي اتفاق الأمة عليه؛ لأنها معصومة عن الخطأ، ولا بد أن يكون اتفاقها موافقًا لما في كتاب الله وسنة رسوله. السعدي:٧٥٣.\nكيف تدل هذه الآية على حجية الإجماع؟\nعَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُنِيبُ ١٠\nوهذان الأصلان كثيرًا ما يذكرهما الله في كتابه؛ لأنهما يحصل بمجموعهما كمال العبد، ويفوته الكمال بفوتهما أو فوت أحدهما؛ كقوله تعالى: ﴿إِيَّاكَ نَعۡبُدُ وَإِيَّاكَ نَسۡتَعِينُ﴾ [الفاتحة: ٥]، وقوله: ﴿فَٱعۡبُدۡهُ وَتَوَكَّلۡ عَلَيۡهِ﴾ [هود: ١٢٣]. السعدي:٧٥٤.\nيكثر في كتاب الله تعالى الجمع بين التوكل والعبادة، فلماذا؟\nذَٰلِكُمُ ٱللَّهُ رَبِّي عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُنِيبُ ١٠\nوجيء في فعل (توكلت) بصيغة الماضي، وفي فعل (أنيب) بصيغة المضارع للإشارة إلى أن توكله على الله كان سابقًا من قبل أن يظهر له تنكر قومه له؛ فقد صادف تنكرُهم منه عبدًا متوكلًا على ربّه،...وأما فعل (أنيب) فجيء فيه بصيغة المضارع للإشارة إلى تجدد الإنابة. ابن عاشور:٢٥/٤٣.\nلماذا جيء في فعل (توكلت) بصيغة الماضي وفي فعل (أنيب) بصيغة المضارع؟"]])